WITH payload AS (SELECT $archive_payload$[{"id":"36275c9d-7490-5d28-8039-1c801a1ca02d","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -سجن املدين استظهار ا حلاله -مخاطبة اجلهات ذات العالقة لالستفسار عن أموال مدعي اإلعسار -شهادة الشهود العدول على إعسار املدين -إثبات اإلعسار بالبينة املعدلة وإفادات الدوائر ذات العالقة.","document_number":"3314438","case_number":"3317798","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/21","year":"1434","subject":"إعسار -سجن املدين استظهار ا حلاله -مخاطبة اجلهات ذات العالقة لالستفسار عن أموال مدعي اإلعسار -شهادة الشهود العدول على إعسار املدين -إثبات اإلعسار بالبينة املعدلة وإفادات الدوائر ذات العالقة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3314438 :‬تاريخه ‪1433/3/21 :‬هـ‬\n                     ‫رقم الدعوى ‪3317798 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 3439282‬تاريخه ‪1434/2/17 :‬هـ‪.‬‬\n\n\n ‫إعســار ‪ -‬ســجن املديــن اســتظهار ًا حلالــه ‪ -‬مخاطبــة اجلهــات ذات‬\n ‫العالقــة لالستفســار عــن أمــوال مدعــي اإلعســار ‪ -‬شــهادة الشــهود‬\n ‫العــدول علــى إعســار املديــن ‪ -‬إثبــات اإلعســار بالبينــة املعدلــة وإفــادات‬\n                                                        ‫الدوائــر ذات العالقــة‪.‬‬\n\n\n\n\n                    ‫‪ -1‬قوله تعالى‪( :‬وإن كان ذو عسرة فنظرة إلى ميسرة)‪.‬‬\n ‫‪ -2‬حديــث أبــي ســعيد رضــي اهلل عنــه قــال أصيــب رجــل يف عهــد رســول‬\n ‫اهلل صلــى اهلل عليــه وســلم يف ثمــار ابتاعهــا فكثــر دينــه فقــال رســول اهلل‬\n ‫صلــى اهلل عليــه وســلم‪« :‬تصدقــوا عليــه فتصــدق عليــه النــاس‪ ،‬فلــم‬\n ‫يبلــغ ذلــك وفــاء دينــه فقــال النبــي صلــى اهلل عليــه وســلم لغرمائــه‬\n                      ‫خــذوا مــا وجــدمت فليــس لكــم إال ذلــك)‪ .‬رواه مســلم‪.‬‬\n ‫‪ -3‬حديــث قبيصــة بــن مخــارق رضــي اهلل عنــه قــال‪ :‬حتملــت حمالــة‬\n ‫وأتيــت رســول اهلل صلــى اهلل عليــه وســلم أســأله فيهــا فقــال‪( :‬أقــم‬\n ‫حتــى تأتينــا الصدقــة فنأمــر لــك بهــا ثــم قــال‪ :‬إن املســألة ال حتــل إال‬\n ‫لثالثــة‪ ...‬ورجــل أصابتــه فاقــة حتــى يقــوم ثالثــة مــن ذوي احلجــا مــن‬\n ‫قومــه فيشــهدوا لقــد أصابــت فالنـ ًا فاقــة حتــى يصيــب قوامـ ًا أو ســداد ًا‬\n                                                                     ‫مــن عيــش)‪.‬‬\n\n\n\n                                                                                      ‫‪154‬‬\n\f      ‫ادعــى مقيــم يف مواجهــة املدعــى عليهمــا بأنــه صــدرت عليــه أحــكام‬\n      ‫بدفــع مبالــغ لصالــح املدعــى عليهمــا وأنــه عاجــز عــن ســدادها وطلــب‬\n      ‫إثبــات إعســاره يف مواجهــة املدعــى عليهمــا‪ ،‬قــرر املدعــى أنــه مســجون‬\n      ‫علــى ذمــة هــذه املبالــغ عشــرين شــهراً‪ ،‬كمــا قــرر أن هــذه الديــون‬\n      ‫ترتبــت بســبب مشــروع زراعــي‪ ،‬أنكــر املدعــى عليهمــا إعســار املدعــى‬\n      ‫وأن لديــه أمــوا ًال وعقــارات ببلــده وأشــقاء يعملــون بالســعودية‪ ،‬أنكــر‬\n      ‫املدعــى وجــود أمــوال وعقــارات لــه ببلــده‪ ،‬طلــب القاضــي مــن املدعــى‬\n      ‫عليهمــا البينــة علــى مــا ذكــراه‪ ،‬قــررا أنــه ال بينــة لديهمــا‪ ،‬طلــب‬\n      ‫القاضــي مــن املدعــي البينــة علــى دعــواه‪ ،‬أحضــر ثالثــة شــهود فشــهدوا‬\n      ‫علــى فقــره وإعســاره‪ ،‬جــرى تعديــل الشــهود‪ ،‬صــدر احلكــم بإثبــات‬\n      ‫إعســار املدعــي وأفهــم املدعــي عليهمــا بــأن عليهمــا إنظــاره إلــى ميســرة‪،‬‬\n      ‫قــرر املدعــى عليهمــا عــدم القناعــة‪ ،‬عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملالحظــة‪ ،‬جــرت الكتابــة ملؤسســة النقــد لإلفــادة عــن‬\n      ‫أرصــدة وحــواالت املدعــى‪ ،‬كمــا جــرت الكتابــة للمــرور لإلفــادة عــن‬\n      ‫الســيارات التــي باســم املدعــى‪ ،‬ورد اجلــواب بعــدم وجــود أرصــدة أو‬\n      ‫ســيارات باســم املدعــى‪ ،‬وجــود حوالــه مببلــغ قليــل للمدعــى لبلده‪،‬جــرى‬\n      ‫عــرض إفــادة الدوائــر علــى املدعــى عليهــم فقــرروا بقولهــم حســبنا اهلل‬\n      ‫ونعــم الوكيــل‪ ،‬جــرى إفهــام املدعــى عليهمــا بــأن لهمــا ميــن املدعــى على‬\n      ‫صحــة دعــواه وأنــه ال يســتطيع ســداد مــا عليــه مــن مبالــغ‪ ،‬رفضــا منــه‬\n      ‫أداء اليمــن‪ ،‬أعيــدت املعاملــة حملكمــة االســتئناف‪ ،‬صــدق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n‫‪155‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنا‪ ...‬القاضي يف احملكمة العامة بتبوك وبناء على املعاملة احملالة لنا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بتبوك‪/‬املكلــف برقــم ‪3317798‬‬\n‫وتاريخ‪1433/11/24‬ه ـ واملقيــدة باحملكمــة برقــم ‪321505242‬‬\n‫وتاريخ‪1433/11/24‬ه ـ حضــر مدعــي اإلعســار ‪ ...‬مصــري اجلنســية‬\n‫مبوجــب رخصــة إقامــة رقــم ‪ ...‬وأدعــى علــى احلاضريــن معــه يف مجلــس‬\n‫احلكــم ‪ ...‬أردنــي اجلنســية مبوجــب رخصــة إقامــة رقــم ‪ ...‬و‪ ...‬ســعودي‬\n‫ا عــن ‪ ...‬مبوجــب‬ ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بصفتــه وكيـ ً‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بتبــوك برقــم ‪2023‬‬\n‫يف ‪1433/1/17‬ه ـ واملخــول لــه حــق املطالبــة واملرافعــة واملخاصمــة‬\n‫واحضــار البينــات واإلقــرار والقناعــة باحلكــم ورفضهــا وحضــور‬\n‫ا يف دعــواه عليهــم لقــد صــدر بحقــي أحــكام تلزمنــي‬    ‫اجللســات ‪ ،‬قائـ ً‬\n‫بســداد مبالــغ ماليــة للمدعــى عليهــم صــادرة مــن هــذه احملكمــة األول‬\n‫بالصــك رقــم ‪6/153‬وتاريــخ ‪1431/11/23‬ه ـ للمدعــى عليــه ‪ ...‬مببلــغ‬\n‫ثالثمائــة وخمســة عشــر ألــف ريــال والثانــي والثالــث للمدعــى عليــه ‪...‬‬\n‫صــادران مــن هــذه احملكمــة برقــم‪ 12/8‬وتاريــخ ‪1432/2/15‬ه ـ مببلــغ‬\n‫ثالثــة وثالثــن ألــف وخمســمائة وخمســة وســتني ريــال والثالــث برقــم‬\n‫‪ 3261201‬وتاريــخ ‪1432/4/2‬ه ـ وأنــا عاجــز عــن ســدادها جميع ـ ًا‬\n‫لكونــي ال أملــك شــيئ ًا مــن حطــام الدنيــا اســتطيع الســداد منــه وقــد‬\n‫أمضيــت بالســجن بســبب هــذه املطالبــات عشــرين شــهر ًا ولــدي أســرة‬\n‫كبيــرة وقــد ضيــق علــي املدعــى عليهــم كثيــر ًا وهــذه الديــون كانــت‬\n\n                                                                                 ‫‪156‬‬\n\f      ‫قــد ترتبــت علــي بســبب مشــروع زراعــي توســعت بــه وخســرت بــه خســارة‬\n      ‫فادحــة وعليــه فأنــا أطلــب إثبــات إعســاري هــذه دعــواي وبعرضهــا علــى‬\n      ‫املدعــى عليهــم احلاضريــن وســؤالهم عنهــا قــرروا جميعـ ًا قائلــن بــأن مــا‬\n      ‫جــاء يف دعــوى املدعــى مــن جهــة املطالبــات والصكــوك الصــادرة بحقــه‬\n      ‫و دخولــه الســجن بســبب هــذه املطالبــات فصحيــح ومــن جهــة أنــه معســر‬\n      ‫ال يســتطيع ســدادنا جميعـ ًا فهــذا غيــر صحيــح هكــذا أجابــوا وبســؤال‬\n      ‫املدعــى عليهمــا هــل لــدى املدعــي أمــوا ًال ميكــن ســدادكما منهــا ؟ قالوا‬\n      ‫بــأن املدعــي ميلــك أمــوا ًال بجمهوريــة مصــر العربيــة فهــو يقــوم بتصديــر‬\n      ‫الســيارات كمــا لــه أشــقاء يعملــون بالزراعــة بقريــة ‪ ........‬بتبــوك هكذا‬\n      ‫قالــوا وبســؤالهم البينــة علــى دفعهــم قالــوا ال بينــة لدينــا علــى مــا دفعنــا به‬\n      ‫وأضــاف املدعــي بأنــي ال أملــك ســوى بيــت شــعر وصندقــة مــن اخلشــب‬\n      ‫يف مصــر هكــذا أضــاف وبســؤال املدعــي البينــة علــى إعســاره قــال‬\n      ‫أحضرهــا يف اجللســة وعليــه رفعــت اجللســة ويف جلســة أخــرى حضــر‬\n      ‫املدعــي كمــا حضــر املدعــى عليــه ‪ ...‬واملدعــى عليــه وكالــة ‪ ...‬وبســؤال‬\n      ‫ال مــن ‪ ...‬مصــري‬   ‫املدعــي عــن البينــة التــي وعــد بإحضارهــا أحضــر ك ً‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقم ‪ ...‬املولــود بتاريخ ‪14381/5/13‬هـ‬\n      ‫ويعمــل مبعــارض الســيارات بتبــوك وال تربطــه صلــة قرابــة بأطــراف‬\n      ‫اخلصومــة حســب إفادتــه و‪ ...‬مصــري اجلنســية مبوجــب رخصــة اإلقامــة‬\n      ‫رقــم ‪ ...‬املولــود بتاريــخ ‪1959/3/1‬م ويعمــل مبعــارض الســيارات بتبــوك‬\n      ‫وال تربطــه صلــة قرابــة بأطــراف اخلصومــة حســب إفادتــه و‪...‬مصــري‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬املولــود بتاريــخ ‪1970/1/1‬م‬\n      ‫ويعمــل ب ـ ‪ ........‬بتبــوك وال تربطــه صلــة قرابــة بأطــراف اخلصومــة حســب‬\n      ‫إفادتــه وبســؤالهم عمــا لديهــم مــن شــهادة شــهد كل واحــد منهــم بقولــه‬\n\n\n‫‪157‬‬\n\f‫أشــهد بــاهلل أن املدعــي معســر ال يســتطيع ســداد املدعــى عليهــم ونحــن‬\n‫نعرفــه منــذ أكثــر مــن ســبع ســنوات هكــذا شــهد كل واحــد منهــم‬\n‫وبعــرض الشــهود وشــهادتهم علــى املدعــى عليهمــا أجــاب املدعــى عليــه‬\n‫‪ ...‬بقولــه الشــهود ال أعرفهــم ال بخيــر وال بشــر ومــن جهــة شــهادتهم‬\n‫فهــي صحيحــة فهــو داخــل الســعودية ال ميلــك شــيئ ًا يســتطيع ســدادنا‬\n‫منــه ولكنــه ميلــك يف مصــر عقــارات كثيــرة كمــا أجــاب املدعــى‬\n‫عليــه وكالــة ‪...‬بقولــه الشــهود ال أعرفهــم ال بخيــر وال بشــر وشــهادتهم‬\n‫داخــل الســعودية صحيحــة فهــو معســر ال ميلــك شــيئ ًا ولكنــه ميلــك يف‬\n‫مصــر عقــارات كثيــرة هكــذا قــال وبطلــب تعديــل الشــهود مــن املدعــي‬\n‫ال مــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬      ‫أحضــر ك ً‬\n‫و‪ ...‬بنجاليشــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬والذيــن شــهدوا‬\n‫بعدالــة الشــهود واســتقامتهم ومحافظتهــم علــى صــاة اجلماعــة هكــذا‬\n‫شــهدا ثــم ســألت املدعــى عليهمــا هــل تعلمــون أن املدعــي قــام بتحويــل‬\n‫مبالــغ ماليــة كبيــرة ملصــر حتــى يتســنى االستفســار مــن مؤسســة النقد؟‬\n‫فقــاال ال نعلــم شــيئ ًا مــن ذلــك وال ميكــن أن يقــوم بتحويــل املبالــغ املاليــة‬\n‫عــن طريــق البنــوك وإمنــا يقــوم بتحويلهــا بطــرق غيــر نظاميــة هكــذا قــاال‬\n‫ونظــر ًا النتهــاء وقــت اجللســة فقــد رفعت ويف جلســة أخــرى حضر املدعي‬\n‫كمــا حضــر املدعــى عليهمــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابة‬\n‫ولقولــه تعالــى «وإن كان ذو عســرة فنظــرة إلــى ميســرة» وحلديــث أبــي‬\n‫ســعد رضــي اهلل عنــه قــال أصيــب رجــل يف عهــد رســول اهلل صلــى اهلل‬\n‫عليــه وســلم يف ثمــار ابتاعهــا فكثــر دينــه فقــال رســول اهلل صلــى اهلل‬\n‫عليــه وســلم (تصدقــوا عليــه فتصــدق عليــه النــاس فلــم يبلــغ ذلــك وفــاء‬\n‫دينــه فقــال النبــي صلــى اهلل عليــه وســلم لغرمائــه (خــذوا مــا وجــدمت‬\n\n\n                                                                                          ‫‪158‬‬\n\f      ‫فليــس لكــم إال ذلــك ) رواه مســلم وحلديــث قبيصــة بــن مخــارق رضــي‬\n      ‫اهلل عنــه قــال حتملــت حمالــة وأتيــت رســول اهلل صلــى اهلل عليــه وســلم‬\n      ‫أســأله فيهــا فقــال « أقــم حتــى تأتينــا الصدقــة فنأمــر لــك بهــا ثــم قــال‬\n      ‫إن املســألة ال حتــل إال لثالثــة ‪ ...‬ورجــل أصابتــه فاقــه حتــى يقــوم ثالثــة‬\n      ‫مــن ذوي احلجــا مــن قومــه فيشــهدون لقــد أصابــت فالن ـ ًا فاقــه حتــى‬\n      ‫يصيــب قوم ـ ًا أو ســداد ًا مــن عيــش» وللبينــة املعدلــة التعديــل الشــرعي‬\n      ‫علــى أن مدعــي معســر ال يســتطيع ســداد املدعــى عليهــم وملــا ذكــر‬\n      ‫فقــد ثبــت لــدي إعســار املدعــي ‪ ...‬وبــه حكمــت وأفهمــت املدعــى عليهــم‬\n      ‫بــأن عليهــم إنظــاره إلــى ميســرة وبإعــان احلكــم قــرر املدعــى عليهمــا‬\n      ‫عــدم قناعتهمــا بــه فأفهمــوا بــان عليهــم مراجعــة احملكمــة خــال يومــن‬\n      ‫الســتالم نســخة احلكــم لتقــدمي الئحتهمــا االعتراضيــة خــال ثالثــن‬\n      ‫يومـ ًا وعنــد تأخرهمــا يف تســليم الالئحــة االعتراضيــة يســقط حقهمــا يف‬\n      ‫طلــب االســتئناف ويكتســب احلكــم القطعيــة ففهمــا ذلــك وصلــى اهلل‬\n       ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1433/3/20‬ه ـ‬\n      ‫احلمــد هلل وحــده ففــي يــوم االثنــن املوافــق ‪1433/10/16‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10:10‬وفيهــا حضــر املدعــى عليــه ‪ ...‬ولــم يحضــر‬\n      ‫مدعــي اإلعســار وكان قــد جــرى منــا رفــع احلكــم وصــورة ضبطــه‬\n      ‫وكافــة أوراق املعاملــة إلــى محكمــة االســتئناف مبنطقــة اجلــوف‬\n      ‫فعــاد احلكــم بكتــاب فضيلــة رئيســها رقــم ‪ 331110317‬وتاريــخ‬\n      ‫‪1433/8/7‬ه ـ وبرفقــه القــرار رقــم ‪ 33322522‬يف ‪1433/7/1‬ه ـ‬\n      ‫ونــص املفيــد وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة لوحــظ مــا يلــي ‪ :‬أوال ‪ :‬لــم يتــم تطبيــق مقتضــى املــادة‬\n      ‫‪ 12/231‬مــن الالئحــة التنفيذيــة لنظــام املرافعــات الشــرعية بالتحــري‬\n\n\n‫‪159‬‬\n\f‫عــن أمــوال املدعــي مــن قبــل اجلهــات املختصــة كمــا لــم تتــم الكتابــة‬\n‫مــن قبــل احملكمــة ملؤسســة النقــد حســب التعميــم رقــم ‪/13‬ت‪2527/‬‬\n‫وتاريــخ ‪1425/10/7‬ه ـ ‪ .‬ثانيــا‪ :‬لــم يتــم توقيــع املدعــي عليــه ‪ ...‬يف اجللســة‬\n‫املؤرخــة يف ‪1433/3/20‬ه ـ ثالثــا‪ :‬قــدم ‪ ...‬الالئحــة االعتراضيــة املقيــدة‬\n‫برقــم ‪ 33778481‬وتاريــخ ‪1433/4/25‬ه ـ وذكــر أنــه وكيــل عــن ‪...‬‬\n‫ولــم يرفــق فضيلتــه صــورة مــن وكالتــه والبــد منــذ ذلــك فعلــى فضيلتــه‬\n‫مالحظــه مــا ذكــر وإكمــال الــازم حســب التعليمــات أ ‪.‬هــ‪ ،‬وعليــه‬\n‫أجيــب أصحــاب الفضيلــة ـ ســلمهم اهلل ـ بأنــه جــرى الكتابــة للمؤسســة‬\n‫النقــد مبوجــب كتابنــا رقــم ‪ 331591020‬يف ‪1433/8/24‬ه ـ ولــم‬\n‫تردنــا اإلفــادة حتــى تاريخــه كمــا جــرى منــا الكتابــة ملديــر شــرطة‬\n‫منطقــة تبــوك مبوجــب كتابنــا رقــم ‪ 331591115‬يف ‪1433/8/24‬ه ـ‬\n‫وحتــى تاريخــه لــم تردنــا اإلفــادة ‪ ،‬أمــا الفقــرة الثانيــة فقــد مت إكمالهــا‬\n‫ا عنــه وعليــه‬ ‫وأمــا الفقــرة الثالثــة فلــم يحضــر املدعــى عليــه وال وكي ـ ً‬\n‫رفعــت اجللســة الســاعة ‪ 10 : 26‬وأجلــت إلــى حــن ورود اجلــواب مــن‬\n‫اجلهــات احلكوميــة املذكــورة ويف يــوم الســبت املوافق‪1434/01/17‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 35‬وفيهــا حضــر املدعــي كمــا حضــر‬\n‫املدعــى عليــه ‪ ...‬واملدعــى عليــه وكالــة ‪ ...‬وكان قــد وردتنــا اإلفــادة مــن‬\n‫مديــر مؤسســة النقــد بتبــوك برقــم ‪ 33/2571‬وتاريــخ ‪1433/12/1‬ه ـ‬\n‫ونــص املفيــد منهــا نــود إفــادة فضيلتكــم أن املؤسســة قامــت بالتعميــم‬\n‫علــى البنــوك واملصــارف العاملــة باململكــة وتلقــت املؤسســة إجابــة‬\n‫كل مــن ‪ 1‬ـ مصــرف الراجحــي أفــاد بوجــود عضويــة حــواالت باســم‬\n‫املذكــور أعــاه برقــم ‪ ......‬وأنــه لــم يتــم عليهــا أي عمليــة حتويــل ‪ 2‬ـ‬\n‫مجموعــة ‪ ........‬املاليــة أفــادت بوجــود حســاب حوالــه باســم املذكــور‬\n\n\n                                                                                       ‫‪160‬‬\n\f      ‫أعــاه برقــم ‪ ......‬وأن آخــر حوالــه كانــت مببلــغ ( ‪ ) 550.16‬دوالر‬\n      ‫أمريكــي وبتاريــخ ‪1429/1/25‬ه ـ إلــى جمهوريــة مصــر العربيــة لصالح‬\n      ‫املســتفيد ‪ ...‬كمــا تلقــت املؤسســة إجابــات باقــي البنــوك واملصــارف‬\n      ‫العاملــة باململكــة ومفادهــا عــدم وجــود أيــة أرصــدة أو حســابات لديهــم‬\n      ‫أو لــدى فروعهــم العاملــة باململكــة تخــص املذكــور أعــاه أ‪.‬ه ـ ‪ ،‬كمــا‬\n      ‫وردنــا كتــاب مديــر شــرطة منطقــة تبــوك رقــم ‪ 18/4159/28‬وتاريــخ‬\n      ‫‪1433/12/19‬ه ـ ومرفقــا ً بــه كتــاب مديــر إدارة مــرور تبــوك ونــص‬\n      ‫املفيــد منــه نفيدكــم بأنــه مت إجــراء البحــث وأتضــح أنــه يوجــد لديــه‬\n      ‫ســيارة واحــده مصــدرة للخــارج أ ‪.‬ه ـ ‪ ،‬وبعرضــه علــى املدعــى عليهــم‬\n      ‫قالــوا حســبنا اهلل ونعــم الوكيــل هكــذا قالــوا وبعــرض ميــن املدعــي‬\n      ‫علــى املدعــى عليهمــا علــى أنــه ال يســتطيع ســدادهما رفضــا منــه أداء‬\n      ‫اليمــن وقــال بأنــه ال يتــورع عنهــا هكــذا قــاال عليــه فقــد قــررت إعــادة‬\n      ‫كامــل أوراق املعاملــة إلــى محكمــة االســتئناف مبنطقــة اجلــوف حســب‬\n      ‫املتبــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم حــرر يف ‪1434/1/17‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/03/04‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12 : 15‬وكان قــد جــرى رفــع احلكــم وصورة‬\n      ‫ضبطــه وكافــة أوراق املعاملــة إلــى محكمــة االســتئناف مبنطقــة‬\n      ‫اجلــوف فعــاد احلكــم مصادق ـ ًا عليــه بالقــرار رقــم ‪ 3439282‬وتاريــخ‬\n      ‫‪1434/2/17‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                              ‫حــرر يف ‪1434/3/4‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائــرة احلقوقيــة‬\n      ‫األولــى يف محكمــة االســتئناف مبنطقــة اجلــوف علــى املعاملــة الــواردة‬\n\n\n‫‪161‬‬\n\f‫مــن فضيلــة رئيــس احملكمــة العامــة يف تبــوك املكلــف الشــيخ ‪...........‬‬\n‫برقم ‪ 331531503‬وتاريخ ‪1434/1/20‬هـ املقيدة لدى هذه احملكمة‬\n‫برقــم ‪ 34371925‬وتاريــخ ‪1434/2/13‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلتــه برقــم ‪ 33144388‬وتاريــخ ‪1433/3/21‬هـ املتعلق بدعوى‪/‬‬\n‫‪ ..........‬مصــري اجلنســية ضــد‪ /‬عــدة أشــخاص يف إثبــات إعســار وقــد‬\n‫تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وباالطــاع‬\n‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك وصــورة ضبطــه بنــاء‬\n‫علــى قرارنــا رقــم ‪ 33322522‬وتاريــخ ‪1433/7/1‬ه ـ فــإن الدائــرة تقــرر‬\n‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                              ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                  ‫‪162‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":154,"source_page_end":162,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"199a1e2592964dbb1080602e64c3c5b46ecd8e522a2707526925a7ee61ff9fe7","normalized_text_hash":"a34a72b39c438e83d22ff92f31204b7ed2efa4ba2e3f2c0f45557ce9cb2e610f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p154-3314438"},{"id":"31d115cc-9aa4-51fa-8f8d-236d87019a14","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة املدعي إثبات اإلعسار للفقر -عدم موافقة املدعى عليه على إثبات إعسار املدعي -خطاب مؤسسة النقد بوجود حساب جاري للمدعي وحركة إيداعات وسحوبات وحتويات مببالغ يسيرة -شهادة الشهود العدول باإلعسار -حلف املدعي اليمن -ثبوت إعسار املدعي -احلكم بتسليم املبلغ املودع يف حساب املدعي للمدعى عليه وإلزام دائنه باإلنظار حلن ميسرة .","document_number":"3437750","case_number":"50920215","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/16","year":"1434","subject":"إعسار -مطالبة املدعي إثبات اإلعسار للفقر -عدم موافقة املدعى عليه على إثبات إعسار املدعي -خطاب مؤسسة النقد بوجود حساب جاري للمدعي وحركة إيداعات وسحوبات وحتويات مببالغ يسيرة -شهادة الشهود العدول باإلعسار -حلف املدعي اليمن -ثبوت إعسار املدعي -احلكم بتسليم املبلغ املودع يف حساب املدعي للمدعى عليه وإلزام دائنه باإلنظار حلن ميسرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/16 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪3437750 :‬‬\n                          ‫َر ْق ُم الدعوى‪50920215 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫تاريخه‪1434/4/20 :‬هـ‬    ‫‪34191587‬‬\n\n\n       ‫إعســار‪ -‬مطالبــة املدعــي إثبــات اإلعســار للفقــر‪ -‬عــدم موافقــة املدعــى‬\n       ‫عليــه علــى إثبــات إعســار املدعــي‪ -‬خطــاب مؤسســة النقــد بوجــود‬\n       ‫حســاب جــاري للمدعــي وحركــة إيداعــات وســحوبات وحتويــات‬\n       ‫مببالــغ يســيرة‪ -‬شــهادة الشــهود العــدول باإلعســار‪ -‬حلــف املدعــي‬\n       ‫اليمــن‪ -‬ثبــوت إعســار املدعــي‪ -‬احلكــم بتســليم املبلــغ املــودع يف حســاب‬\n             ‫املدعــي للمدعــى عليــه وإلــزام دائنــه باإلنظــار حلــن ميســرة ‪.‬‬\n\n\n\n\n                          ‫ان ُذو ُع ْس َر ٍة فَ َن ِظ َر ٌة ِإ َلى َم ْي َس َرةٍ}‬\n                                                                                ‫ك َ‬ ‫‪ .1‬قوله تعالى { َو ِإن َ‬\n       ‫‪ .2‬قولــه صلــى اهلل عليــه وســلم لغرمــاء الــذي كثــر دينــه (( خــذوا مــا‬\n                                                                     ‫وجــدمت وليــس لكــم إال ذلــك ))‬\n       ‫‪ .3‬قــال ابــن قدامــة يف الشــرح الكبيــر (( ومتــى ثبــت إعســاره عنــد‬\n                                       ‫احلاكــم لــم يجــز مطالبتــه وال مالزمتــه ))‬\n       ‫‪ .4‬قــال البهوتــي يف الــروض املربــع (( ومــن لــم يقــدر علــى وفــاء شــيء‬\n                                ‫مــن دينــه لــم يطالــب بــه وحــرم حبســه ومالزمتــه))‬\n                ‫‪ .5‬املادة ‪ 231‬من نظام املرافعات الشرعية والئحتها التنفيذية‪.‬‬\n       ‫‪ .6‬مــا قــرره أهــل العلــم ‪ :‬مــن أن مــن كان عليــه ديــن وادعــى اإلعســار‬\n       ‫وكان دينــه علــى عــوض كالبيــع والقــرض ُحبــس إال أن يقيــم بينــة‬\n                                                                             ‫علــى نفــاذ مالــه وإعســاره ‪.‬‬\n\n‫‪163‬‬\n\f‫‪ .7‬ملــا قــرره بعــض أهــل العلــم ‪ :‬مــن طلــب اليمــن مــن مدعــي اإلعســار‬\n‫ولــو أحضــر بينــة تشــهد لــه بإعســار أو تلــف مــال‪ .‬وهــو القــول الثانــي‬\n                                   ‫للشــافعي واختيــار املوفــق ابــن قدامــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه أنــه صــدر صــك يلــزم املدعــي بتســليم‬\n‫املدعــى عليــه مبلغ ـ ًا وقــدره خمســمائة ألــف ريــال وأن املدعــى عليــه‬\n‫طالــب بتنفيــذ الصــك ولــم يســتطع املدعــي الســداد فتــم إيقــاف املدعــي‬\n‫مــن تاريــخ ‪1431/2/29‬ه ـ ومــا زال موقوفـ ًا وقــرر املدعــي أنــه ال يوجــد‬\n‫لــه مــال وأنــه فقيــر وطلــب إثبــات إعســاره‪ ،‬أجــاب املدعــى عليــه بعــدم‬\n‫املصادقــة علــى إعســار املدعــي‪ ،‬يف جلســة أخــرى حضــر املدعــي ولــم‬\n‫يحضــر املدعــى عليــه ولــم يقــدم عــذر ًا لعــدم حضــوره‪،‬وردت إجابــة‬\n‫مؤسســة النقد ومضمونها وجود حســابات للمدعي مغلقة ســوى حســاب‬\n‫واحــد يوجــد فيــه رصيــد تســعة آالف وســبعمائة وواحــد وخمســون ريــا ًال‬\n‫وثمانيــة وتســعون هللــة‪ ،‬كمــا مت االطــاع علــى احلــواالت واإليداعــات‬\n‫والســحوبات وقــرر ناظــر القضيــة أنهــا غيــر ملفتــة وليســت ذات مبالــغ‬\n‫ماليــة كبيــرة‪ ،‬مت االطــاع علــى مذكــرة توقيــف املدعــي‪ ،‬طلــب ناظــر‬\n‫القضيــة بينــة مــن املدعــي تثبــت إعســاره فأحضــر ثالثــة شــهود شــهدوا‬\n‫بإعســار املدعــي‪ ،‬طلــب ناظــر القضيــة مــن املدعــي بــذل اليمــن علــى‬\n‫صحــة دعــواه فحلــف علــى ذلــك‪ ،‬صــدر حكــم ناظــر القضيــة بتســليم‬\n‫املبلــغ املوجــود يف حســاب املدعــي للمدعــى عليــه وإلــزام املدعــى عليــه‬\n‫بإنظــار املدعــي إلــى حــن ميســرة‪ ،‬نظــر ًا لتعــذر إرســال نســخة للمدعــى‬\n‫عليــه مت بعــث املعاملــة إلــى محكمة االســتئناف فصادقــت على احلكم‪.‬‬\n\n                                                                                  ‫‪164‬‬\n\f      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ........‬القاضي يف احملكمة العامة مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 50920215‬وتاريــخ ‪1431/03/01‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 3122732‬وتاريــخ ‪1431/03/01‬ه ـ ففــي يــوم‬\n      ‫األحد املوافق ‪1433/04/04‬هـ افتتحت اجللســة الســاعة ‪ 12 : 09‬وفيها‬\n      ‫حضــر ‪ .......‬باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪ .......‬وأدعــى‬\n      ‫علــى احلاضــر معــه ‪ .......‬بريطانــي اجلنســية مبوجــب إقامــة رقــم‪ ......‬قائــا‬\n      ‫يف دعــواه عليــة وهــو يحســن العربيــة إن بذمتــي للمدعــى عليــة مبلغــا‬\n      ‫قــدره خمســمائة ألــف ريــال يلزمنــي دفعــه لــه مبوجــب الصــك الصــادر‬\n      ‫منكــم برقــم ‪ 18/200/29‬يف ‪1430/11/27‬ه ـ وإن املدعــى عليــة قــد‬\n      ‫طالــب بتنفيــذ ذلــك الصــك فطلبــت منــي شــعبة تنفيــذ األحــكام دفــع‬\n      ‫هــذا املبلــغ للمدعــى عليــه إال أنــه لفقــري وعــدم قدرتــي علــى ســداد‬\n      ‫هــذا الديــن أو جــزء منــه فقــد مت إيقــايف مــن تاريــخ ‪1431/2/29‬ه ـ‬\n      ‫ومــا زلــت موقوفــا وحيــث ال يوجــد لــدي أي مــال ولكونــي رجــل فقيــر‬\n      ‫لــذا اطلــب إثبــات إعســاري هــذه دعــواي وبســؤال املدعــى عليــة أجــاب‬\n      ‫قائــا وهــو يحســن العربيــة مــا ذكــره املدعــي يف دعــواه مــن أنــه معســر‬\n      ‫وليــس لديــة مــال فغيــر صحيــح حيــث أننــي قــد حولــت هــذا املبلــغ ليبقــى‬\n      ‫أمانــة لديــة وذلــك بنــاء علــى اتفــاق بينــي وبينــه أن أقــوم بتحويــل هــذا‬\n      ‫املبلــغ حلســابه مــن حســابي يف بريطانيــا لعــدم وجــود حســاب لــدي يف أي‬\n      ‫مــن بنــوك اململكــة ثــم إذا حضــرت إلــى اململكــة يقــوم بتســليمي هــذا‬\n      ‫املبلــغ ال تقــدم بطلــب فتــح ســجل جتــاري واالســتثمار بعــد ذلــك إال أننــي‬\n\n‫‪165‬‬\n\f‫حينمــا حضــرت إلــى اململكــة وطلبــت مــن املدعــي تســليمي هــذا املبلــغ‬\n‫رفــض ذلــك وتهــرب منــي وال ميكــن أن يكــون قــد انفــق ذلــك املبلــغ‬\n‫يف مــدة وجيــزة كمــا أن املدعــي لديــة ســجل جتــاري صــادر مــن هيئــة‬\n‫االســتثمار حيــث أنــه مســتثمر يف اململكــة ولديــة حســابات بنكيــة يف‬\n‫بنــوك اململكــة ولديــة عمــارة يف حــي ‪........‬ميلكهــا املدعــي ومســجله‬\n‫باســم شــخص ســعودي وعليــة فإننــي غيــر موافــق علــى اثبــات إعســاره‬\n‫هــذه إجابتــي وبعــرض ذلــك علــى املدعــي أجــاب إن مــا ذكــره املدعــى‬\n‫عليــة غيــر صحيــح والصحيــح أن املدعــي قــد طلــب منــي الدخــول معــي‬\n‫شــريكا يف االســتثمار يف اســتئجار وتشــغيل فنادق للمعتمرين واحلجاج‬\n‫وان يدخــل بنســبة ثالثــن باملائــة ورأس املــال املتفــق علية هو ثالثة ماليني‬\n‫ريــال وقــد دفــع املدعــى عليــة بواســطة احلوالــة مبلــغ اخلمســمائة الــف‬\n‫ريــال إال أنــه قــد طلــب منــي رد هــذا املبلــغ فذهبــت إلــى البنــك وســحبت‬\n‫مبلــغ مائتــي الــف ريــال ووضعتهــا يف شــنطة مــن أجــل تســليمها للمدعــي‬\n‫وكان معــي املدعــي فقــام بســحب الشــنطة منــي وبداخلهــا املبلــغ وهــرب‬\n‫كمــا أننــي قــد ســافرت أنــا واملدعــي الــى دولــه غانــا مــن أجــل التجــارة‬\n‫وكان معــي خمســة وســتني الــف دوالر وتعــادل مائتــن وثالثــة واربعــن‬\n‫الــف ريــال ولكــن ســرق منــي هــذا املبلــغ يف دولــة غانــا ومــا ذكــره‬\n‫املدعــي مــن انــه يوجــد لــدي عمــارة تقــع يف حــي ‪ ........‬املكهــا أنــا وهــي‬\n‫مســجلة باســم شــخص ســعودي فغيــر صحيــح فأنــا ال املــك أي عمــارة‬\n‫او عقــار وليــس لــدي أي مبالــغ يف احلســابات البنكيــة هــذه إجابتــي‬\n‫وبعــرض ذلــك علــى املدعــى عليــة أجــاب ال صحــة ملــا ذكــره املدعــي وأنــا‬\n‫لــم أخــذ منــه أي مبلــغ وقــد ذهبــت أنــا وإيــاه إلــى غانــا وقــد ســألته قبــل‬\n‫أن نذهــب كــم املبلــغ الــذي معــك فقــال خمســة االف دوالر وقــد ذهبــت‬\n\n\n                                                                                         ‫‪166‬‬\n\f      ‫معــه مــن أجــل أن اترجــم لــه هنــاك حيــث أنــه ال يجيــد التحــدث باللغــة‬\n      ‫االجنليزيــة ثــم قــررت رفــع اجللســة والكتابــة ملؤسســة النقــد لإلفــادة‬\n      ‫عــن مقــدار املبالــغ املودعــة بحســابات املدعــي واحلــواالت التــي قــام بهــا‬\n      ‫مــن قبــل حتويــل املدعــى عليــة لــه هــذا املبلــغ وأجلــت اجللســة حلــن ورود‬\n      ‫اجلــواب ويف يــوم الثالثــاء املوافــق‪ 1433/07/15‬ه ـ افتتحــت اجللســة‬\n      ‫وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه وقــد جــرت الكتابــة‬\n      ‫ملؤسســة النقــد لإلفــادة عــن املبالــغ املودعــة بحســابات املدعــي واحلــواالت‬\n      ‫التــي قــام بهــا مــن قبــل حتويــل املدعــى عليــه لــه هــذا املبلــغ فــورد جــواب‬\n      ‫مديــر فــرع مؤسســة النقــد رقــم ‪........‬يف ‪1433/5/23‬ه ـ وأرفــق بخطابــه‬\n      ‫كشــف حــواالت وكشــف حســابات املدعــى عليــه وذلــك لــدى كل مــن‬\n      ‫بنــك الريــاض والبنــك الســعودي الفرنســي والبنــك الســعودي البريطانــي‬\n      ‫ولــم يتــم إرفــاق أي كشــوف حســابات تخــص املدعــي والتــي مت طلــب‬\n      ‫اإلفــادة عنهــا‪ .‬ويف يــوم األثنــن املوافــق ‪1434/2/4‬هـ افتتحت اجللســة يف‬\n      ‫موعدهــا الســاعة التاســعة والنصــف صباح ـ ًا فيهــا حضــر املدعــي ولــم‬\n                            ‫يحضــر املدعــى عليــه ولــم يقــدم عــذر ًا لعــدم حضــوره‪.‬‬\n      ‫وقــد جــرت الكتابــة ملؤسســة النقــد لإلفــادة عــن مقــدار املبالــغ املودعــة‬\n      ‫يف حســابات املدعــي لــدى جميــع البنــوك العاملــة باململكــة وجميــع‬\n      ‫احلــواالت التــي قــام بهــا مــن تاريــخ ‪2006/5/27‬م فوردنــا خطــاب مديــر‬\n      ‫فــرع مؤسســة النقــد مبكــة رقــم ‪ ........‬وبــدون تاريــخ واملتضمــن وجــود‬\n      ‫حساب للمدعي يف بنك ‪ ........‬وهو مغلق وال يوجد فيه رصيد وحسابني‬\n      ‫يف مصــرف ‪ ........‬احدهمــا مغلــق وال يوجــد فيــه رصيــد والثانــي حســاب‬\n      ‫جــاري يوجــد فيــه رصيــد قــدره تســعة االف ريــال وســبعمائة وواحــد‬\n      ‫وخمســون ريــا ًال وثمانيــة وتســعون هللــه فقــط كمــا ارفــق بخطــاب مديــر‬\n\n\n‫‪167‬‬\n\f‫مؤسســة النقــد قرص ـ ًا ممغنط ـ ًا فجــرى تشــغيله علــى احلاســب اآللــي‬\n‫فوجدتــه يحتــوي علــى ملــف يعمــل علــى برنامــج االكســل ويحتــوي علــى‬\n‫جــدول بقائمــة االيداعــات والســحوبات والتحويــات مــن وإلــى حســاب‬\n‫املدعــي لــدى مصــرف ‪ ........‬ويوجــد حركــة كبيــرة يف احلســابات وال‬\n‫يظهــر تاريــخ العمليــات التــي متــت وغالــب العمليــات غيــر ملفتــه وليســت‬\n‫ذات مبالــغ كبيــرة ويوجــد ايداعــات وحتويــات إلــى حســاب املدعــي‬\n‫مببالــغ مــا بــن الثمانيــة االف وواحــد وثالثــن الــف ريــال وهــي ليســت‬\n‫كثيــرة ويوجــد حتويــات مــن احلســاب وإلــى حســابات أخــرى وهــي‬\n‫قليلــة جــد ًا واملبالــغ فيهــا بــن ســتة عشــر الــف ريــال وعشــرين الــف ريــال‬\n‫فجــرى ســؤال املدعــي عــن التحويــات التــي اجراهــا مــن حســابه فأجــاب‬\n‫لقــد صرفــت هــذه املبالــغ للشــركة التــي اقمتهــا بينــي وبــن املدعــى‬\n‫عليــه ولكنهــا خســرت هــذه الشــركة ثــم جــرى منــي االطــاع علــى‬\n‫مذكــرة اإليقــاف الصــادرة بحــق املدعــي انفــاذ ًا للصــك الصــادر عليــه‬\n‫بإلزامــه بدفــع املبــغ احملكــوم بــه عليــه والصــادرة مــن شــرطة العاصمــة‬\n‫املقدســة رقــم ‪ ........‬يف ‪1431/2/29‬ه ـ ومــا زال املدعــي مــن ذلــك الوقــت‬\n‫ســجين ًا لعــدم ســداده لهــذا املبلــغ فطلبــت منــه البينــة علــى دعــواه أحضــر‬\n‫للشــهادة وادائهــا ‪ ........‬بنجالديــش اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫الصــادرة مــن جــوازات جــدة برقــم ‪ ........‬وهــو مــن مواليــد عــام ‪1941‬‬\n‫وافــاد الشــاهد بأنــه يســكن يف حــي ‪........‬وعالقتــه باملدعــي هــو أنــه‬\n‫جــاره يف احلــي الــذي يســكنون فيــه وأمــا املدعــى عليــه فليــس بينهمــا‬\n‫عالقــة كمــا أحضــر باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫‪ ...‬مولــود بتاريــخ ‪1947/7/1‬م وافــاد بانــه يســكن يف حــي ‪........‬وجهــة‬\n‫اتصالــه باملدعــي هــو أن زوجتــه وزوجــة املدعــي أخــوات إال أن زوجــة‬\n\n\n                                                                                        ‫‪168‬‬\n\f      ‫املدعــي قــد توفيــت وأمــا املدعــى عليــه فــا عالقــة بينهمــا كمــا أحضــر‬\n      ‫للشــهادة ‪ ........‬باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬وهــو‬\n      ‫مولــود بتاريــخ ‪1407/7/1‬ه ـ وأفــاد الشــاهد بأنــه يســكن يف حــي ‪........‬‬\n      ‫وعالقتــه باملدعــي بأنــه جــار لــه يف نفــس احلــي وأمــا املدعــى عليــه فليــس‬\n      ‫بينهمــا عالقــة وبســؤال الشــهود عــن مــا لديهــم شــهد كل واحــد منهمــا‬\n      ‫منفــرد ًا قائلــن نشــهد بأننــا نعــرف املدعــي احلاضــر معرفــة تامــة مــن‬\n      ‫فتــرة طويلــة وهــو اآلن رجــل فقيــر ومعســر وليــس لديــة أي مــال ثابــت أو‬\n      ‫منقــول يســتطيع ســداد مــا بذمتــه أو بعضـ ًا ممــا بذمتــه وأن البيــت الــذي‬\n      ‫ذكــره املدعــى عليــه ويقــع يف املســفلة ليــس ملــك ًا للمدعــي هــذا مــا‬\n      ‫لدينــا وبــه نشــهد فطلبــت مــن املدعــي معدلــن لبينتــه فطلــب املهلــة لذلــك‬\n      ‫ويف يــوم االثنــن املوافــق ‪1434/02/11‬ه ـ افتتحــت اجللســة يف موعدهــا‬\n      ‫الســاعة احلاديــة عشــر والنصــف وفيهــا حضــر املدعــي ولــم يحضــر‬\n      ‫ال مــن ‪........‬‬\n                     ‫املدعــى عليــه وبطلــب معدلــن مــن املدعــي لبينتــه أحضــر ك ً‬\n      ‫باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ........‬وباكســتاني‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ........‬وشــهدا بعدالــة وثقــة وأمانــة‬\n      ‫البينــة التــي أحضرهــا املدعــي وهــم ‪ ........‬و ‪ ........‬و ‪ ........‬و ‪ ........‬ثــم‬\n      ‫جــرى ســؤال املدعــي هــل يســتعد ببــذل اليمــن علــى مــا جــاء يف دعــواه‬\n      ‫ا واهلل‬  ‫مــن اإلعســار وتلــف املــال فأجــاب نعــم وبطلبهــا منــه حلــف قائ ـ ً‬\n      ‫العظيــم إننــي معســر وليــس لــدي أي مــال يزيــد عــن حاجتــي وحاجــة مــن‬\n      ‫أعــول وأن مــا كان مــن مــال عنــدي ســابق ًا فقــد تلــف ولــم أخــف أي مــال‬\n                       ‫ظاهــر أو باطــن ثابــت أو منقــول واهلل علــى مــا أقــول شــهيد‪.‬‬\n      ‫فبنــاء علــى مــا ســبق مــن دعــوى املدعــي وإجابــة املدعــى عليــه ولعــدم‬\n      ‫البينــة لــدى املدعــى عليــه علــى مــا دفــع بــه وبنــاء علــى اطالعــي علــى‬\n\n\n‫‪169‬‬\n\f‫الصــك الصــادر بحــق املدعــي املشــار إليــه يف الدعــوى واالطــاع علــى‬\n‫ســبب االســتحقاق وبنــاء اطالعــي علــى مذكــرة التوقيــف الصــادرة‬\n‫بحــق املدعــى عليــه وحيــث مت إجــراء البحــث والتحــري عــن أمــوال‬\n‫املدعــي ولــم يتــم العثــور علــى شــيء وبنــاء علــى خطــاب مؤسســة النقــد‬\n‫العربــي الســعودي وبنــاء علــى مــا شــهدت بــه البينــة املعدلــة شــرع ًا ولقولــه‬\n‫تعالــى‪( :‬وإن كان ذو عســرة فنظــرة إلــى ميســرة) ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم لغرمــاء الــذي كثــر دينــه ‪( :‬خــذوا مــا وجــدمت‪ ،‬وليــس‬\n‫لكــم إال ذلــك) وملــا قــرره أهــل العلــم مــن أن مــن لــم يقــدر علــى وفــاء‬\n‫دينــه لعســر لــم يطالــب بــه وحــرم حبســه‪ .‬قــال ابــن قدامــة يف الشــرح‬\n‫الكبيــر‪( :‬ومتــى ثبــت إعســاره عنــد احلاكــم‪ ،‬لــم يجــز مطالبتــه وال‬\n‫مالزمتــه)‪ ،‬وقــال البهوتــي يف الــروض املربــع‪( :‬ومــن لــم يقــدر علــى وفــاء‬\n‫شــي ٍء مــن دينــه لــم يطالــب بــه وحــرم حبســه ومالزمتــه)‪ ،‬وملــا قــرره أهــل‬\n‫العلــم أيض ـاً‪ :‬بــأن مــن كان عليــه ديــن وادعــى اإلعســار وكان دينــه‬\n‫علــى عــوض كالبيــع والقــرض ُح ِبــس إال أن يقيــم بينــة علــى نفــاذ مالــه‬\n‫وإعســاره‪ .‬وملــا قــرره بعــض أهــل العلــم مــن طلــب اليمــن مــن مدعــي‬\n‫اإلعســار ولــو أحضــر بينــة تشــهد لــه بإعســار أو تلــف مــال وهــو القــول‬\n‫الثانــي للشــافعي واختيــار املوفــق ابــن قدامــة وبنــاء علــى املــادة الواحــدة‬\n‫والثالثــن بعــد املائتــن والئحتهــا التنفيذيــة وحيــث بقــي املدعــي موقوفـ ًا‬\n‫مــدة تزيــد علــى الثــاث ســنوات وهــي مــدة كافيــة جــد ًا يف اســتظهار‬\n‫حالــة لذلــك كلــه أمــرت بتســليم املبلــغ املــودع يف حســاب املدعــي وقــدره‬\n‫تســعة االف ريــال وســبعمائة وواحــد وخمســون ريــا ًال وثمانيــة وتســعون‬\n‫هللــه للمدعــى عليــه وذلــك انفــاذا للصــك الصــادر بحــق املدعــي وثبــت‬\n‫لــدي إعســار املدعــي ‪........‬يف بقيــة املبلــغ املســتحق بذمتــه للمدعــى عليــه‬\n\n\n                                                                                         ‫‪170‬‬\n\f      ‫وألزمــت دائنــه إنظــاره إلــى ميســرة وبذلــك حكمــت ومت إعــان احلكــم‬\n      ‫بتاريــخ ‪1434/2/11‬ه ـ وقــررت اعتبــار احلكــم حضوريـ ًا يف حق املدعى‬\n      ‫عليــه بنــاء علــى املــادة ‪ 1/55‬ونظــر ًا لتعــذر تســليم املدعــى عليــه نســخة‬\n      ‫مــن إعــام احلكــم لكونــه يقيــم يف اململكــة املتحــدة ويتعــذر تســليم‬\n      ‫املدعــى عليــه نســخة مــن إعــام احلكــم وبنــاء علــى املــادة ‪ 5/176‬مــن‬\n      ‫نظــام املرافعــات فقــد قــررت بعــث احلكــم حملكمــة االســتئناف ومت‬\n      ‫إقفــال اجللســة الســاعة الثانيــة عشــر وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n                   ‫نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/11‬هــ‪.‬‬\n      ‫ويف يــوم الســبت املوافــق ‪1434/05/25‬ه ـ افتتحــت اجللســة وقــد‬\n      ‫وردت املعاملــة مــن محكمــة االســتئناف وبرفقهــا الصــك وقــد ظهــر‬\n      ‫عليــه باملوافقــة ونصــه تظهيــرات الدائــرة احلقوقيــة الرابعــة مبحكمــة‬\n                                                   ‫االســتئناف مبكــة املكرمــة ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪3437750‬‬\n      ‫وتاريــخ ‪1434/2/16‬ه ـ الصــادر مــن فضيلــة الشــيخ واصدرنــا القــرار‬\n      ‫رقــم ‪ 34191587‬وتاريــخ ‪1434/4/20‬ه ـ املتضمــن املوافقــة علــى‬\n      ‫احلكــم قاضــي اســتئناف ‪ ........‬قاضــي اســتئناف ‪ ........‬رئيــس الدائــرة‬\n      ‫‪ ........‬تواقيعهــم واختامهــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/25‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n      ‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل بعــدد‬\n      ‫‪ 3437750‬وتاريــخ ‪1434/2/16‬ه ـ املتضمــن دعــوى ‪ ........‬باكســتاني‬\n\n\n‫‪171‬‬\n\f‫اجلنســية ضــد ‪ ........‬بريطانــي اجلنســية واحملكــوم فيــه مبــا دون باطنــه‬\n‫وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ .‬وصلــى‬\n                        ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪172‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":163,"source_page_end":172,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"95c3d81b777f350bab4b166e78fc919a503d6babed1f04a9ae5a7fed10a2efed","normalized_text_hash":"1f7e24fe7e7d58fd627d7d4f0c3f90d1dace46baec5fb484ed2dcee8e4dc2f3f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p163-3437750"},{"id":"a0448fc4-807e-5632-9ee6-07aed9172a1c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -سبق احلكم على املدعى بالسجن ودفع مبلغ مالي بسبب االشتراك يف جرمية نصب واحتيال -مطالبة بإثبات اإلعسار -قاعدة رد دعوى اإلعسار إذا كان املبلغ احملكوم به بسبب جرمية -احلكم برد دعوى املدعى واالستمرار يف سجنه حتى ينهي احلق اخلاص .","document_number":"3449400","case_number":"3495396","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/27","year":"1434","subject":"إعسار -سبق احلكم على املدعى بالسجن ودفع مبلغ مالي بسبب االشتراك يف جرمية نصب واحتيال -مطالبة بإثبات اإلعسار -قاعدة رد دعوى اإلعسار إذا كان املبلغ احملكوم به بسبب جرمية -احلكم برد دعوى املدعى واالستمرار يف سجنه حتى ينهي احلق اخلاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/2/27 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3449400 :‬‬\n                          ‫َر ْق ُم الدعوى‪3495396 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34175864‬تاريخه‪1434/4/1 :‬هـ‬\n\n\n      ‫إعســار‪ -‬ســبق احلكــم علــى املدعــى بالســجن ودفــع مبلــغ مالــي بســبب‬\n      ‫االشــتراك يف جرمية نصب واحتيال‪ -‬مطالبة بإثبات اإلعســار‪ -‬قاعدة‬\n      ‫رد دعــوى اإلعســار إذا كان املبلــغ احملكــوم بــه بســبب جرميــة‪ -‬احلكــم‬\n      ‫بــرد دعــوى املدعــى واالســتمرار يف ســجنه حتــى ينهــي احلــق اخلــاص ‪.‬‬\n\n\n\n\n      ‫خطــاب املقــام الســامي رقــم ‪/4‬ص‪ 21795/‬يف ‪1402/9/17‬ه ـ املتضمــن‬\n      ‫املوافقــة واعتمــاد مــا جــاء يف قــرار مجلــس القضــاء األعلــى رقــم‬\n      ‫‪ 135/5/36‬وتاريــخ ‪1402/8/7‬ه ـ املتضمــن قواعــد عامــة إلثبــات‬\n      ‫اإلعســار‪ -‬وبنــاء علــى الفقــرة الثانيــة ونصهــا ‪( :‬مــن كانــت عليــه‬\n      ‫أمــوال خاصــة بســبب جرائــم تعمــد ارتكابهــا مــن ســرقات و نحوهــا ثــم‬\n      ‫أدعــى العســر عنــد القبــض عليــه ليتخلــص مــن تبعــات هــذه األمــوال‬\n      ‫وكان إثبــات عســره يتيــح لــه اإلجــراء أو ميكنــه مــن الهــرب إن كان‬\n      ‫أجنبيـ ًا وكان حبســه أقــرب إلــى حصــول املصلحــة ودفــع املفســدة فإنــه‬\n            ‫يتعــن اتخــاذ مــا يحقــق املصالــح املرجــوة ويدفــع املفاســد ‪. )...‬‬\n\n\n\n\n      ‫ادعــى مقيــم (مديــن) يف مواجهــة املدعــى عليــه الغائــب (الدائــن) أنــه‬\n      ‫حكــم عليــه بالســجن ودفــع مبلــغ ثالثمائــة ألــف ريــال للمدعــى عليــه‬\n\n‫‪173‬‬\n\f‫الدائــن‪ ،‬قــرر املدعــي أنــه ال يســتطيع دفــع هــذا املبلــغ وطلــب إثبــات‬\n‫إعســاره يف مواجهــة دائنــه‪ ،‬جــرى رجــوع القاضــي إلــى القــرار الصــادر‬\n‫بحــق مدعــي اإلعســار واملصــدق مــن محكمــة االســتئناف املتضمــن‬\n‫إدانــة مدعــى اإلعســار باالشــتراك يف جرميــة نصــب واحتيــال علــى‬\n‫الدائــن واســتالمه منــه ملبلــغ ثالثمائــة ألــف ريــال‪ ،‬وقــد صــدر احلكــم يف‬\n‫احلــق العــام بإدانــة مدعــي اإلعســار باالشــتراك يف جرميــة نصــب واحتيــال‬\n‫وتعزيــره بالســجن واجللــد‪ ،‬وإلزامــه يف احلــق اخلــاص بدفــع مبلــغ ثالثمائــة‬\n‫ألــف ريــال‪ ،‬بنــاء علــى أن املبلــغ احملكــوم بــه نتيجــة عمليــة نصــب‬\n‫واحتيــال و بنــاء علــى الفقــرة الثانيــة مــن قــرار مجلــس القضــاء األعلــى‬\n‫رقــم ‪ 135/5/36‬وتاريــخ ‪1402/8/7‬ه ـ صــدر احلكــم بــرد دعــوى‬\n‫املدعــي باملطالبــة بإثبــات إعســاره واحلكــم باســتمرار ســجنه حتــى ينهــي‬\n‫احلــق اخلــاص‪ ،‬اعتــرض مدعــي اإلعســار علــى احلكــم‪ ،‬صــدق احلكــم‬\n                                                   ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جــدة‪ /‬املســاعد برقــم ‪3495396‬‬\n‫وتاريــخ ‪1434/02/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34492148‬وتاريــخ‬\n‫‪1434/02/26‬ه ـ ففــي يــوم الثالثــاء املوافق‪1434/02/26‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 :15‬وبنــاء علــى املعاملــة احملالــة لنــا مــن مديــر‬\n‫شــرطة محافظــة جــدة رقــم ‪ 1/41/20/186‬وتاريــخ ‪1434/2/25‬ه ـ‬\n‫حضــر املدعــي ‪...‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪...‬ولــم يحضــر‬\n\n                                                                                    ‫‪174‬‬\n\f      ‫املدعــى عليــه ‪...‬وبســؤاله عــن دعــواه أجــاب بــأن فضيلتكــم حكــم‬\n      ‫بســجني عشــرة أشــهر مــن تاريــخ ‪1433/01/26‬ه ـ ودفــع مبلــغ وقــدره‬\n      ‫ثالثمائــة ألــف ريــال للمدعــى عليــه ‪...‬وأنــا ال اســتطيع دفــع هــذا املبلــغ‬\n      ‫اطلــب إثبــات إعســاري وعجــزي عــن ســداد هــذا املبلــغ هــذه دعــواي‬\n      ‫وعليــه وبعــد االطــاع علــى القــرار الصــادر منــا رقــم ‪ 33332672‬وتاريــخ‬\n      ‫‪1433/07/08‬ه ـ واملصــدق مــن محكمــة االســتئناف واملتضمــن إدانــة‬\n      ‫املدعــي ‪...‬باالشــتراك يف جرميــة نصــب واحتيــال علــى املدعــي اخلــاص‬\n      ‫واســتالمه منــه مبلــغ وقــدره ثالثمائــة ألــف ريال واحلكم بســجنه يف احلق‬\n      ‫العــام عشــرة أشــهر حتســب منهــا مــدة التوقيــف وجلــده ثالثمائــة جلــدة‬\n      ‫ويف احلــق اخلــاص بدفــع مبلــغ وقــدره ثالثمائــة ألــف ريــال للمدعى عليه يف‬\n      ‫هــذه الدعــوى ‪...‬وبنــاء علــى خطــاب املقــام الســامي رقــم ‪/4‬ص‪21795/‬‬\n      ‫يف ‪1402/09/17‬ه ـ واملتضمــن املوافقــة واعتمــاد مــا جــاء يف قــرار‬\n      ‫مجلس القضاء األعلى رقم ‪ 135/5/36‬يف ‪1402/08/07‬هـ واملتضمن‬\n      ‫قواعــد عامــة إلثبــات اإلعســار وبنــاء علــى الفقرة الثانية منــه ونصها (من‬\n      ‫كانــت عليــه أمــوال خاصــة بســبب جرائــم تعمــد ارتكابهــا مــن ســرقات‬\n      ‫ونحوهــا ثــم ادعــى العســر عنــد القبــض عليــه ليتخلــص مــن تبعــات هــذه‬\n      ‫األمــوال وكان إثبــات عســره يتيــح لــه اإلجــراء أو ميكنــه مــن الهــرب أن‬\n      ‫كان أجنبيــا وكان حبســه أقــرب إلــى حصــول املصلحــة ودفــع املفســدة‬\n      ‫فإنــه يتعــن اتخــاذ مــا يحقــق املصالــح املرجــوة ويدفــع املفاســد عــن هــذه‬\n      ‫البــاد ويعــن علــى اســتمرار األمــن فيهــا ويــردع املجرمــن عــن اإلجــرام‬\n      ‫ويزجــر مــن يف نفســه مــرض) ولكــون املبلــغ احملكــوم علــى املدعــي‬\n      ‫كان بســبب جرميــة نصــب واحتيــال لــذا فقــد حكمــت بــرد دعــوى‬\n      ‫املدعــي باملطالبــة بإثبــات إعســاره وقــررت االســتمرار يف ســجنه حتــى‬\n\n\n‫‪175‬‬\n\f‫ينهــي احلــق اخلــاص وبعــرض احلكــم عليــه قــرر عــدم القناعــة وطلــب رفــع‬\n‫املعاملــة حملكمــة االســتئناف بــدون الئحــة اعتراضيــة فعليــه قــررت رفــع‬\n‫املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/26‬ه ـ‬\n‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n‫مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى ه ــذا احلكــم الص ــادر مــن‬\n‫فضي ــلة الشــيخ ‪...‬القاضــي باحملكمــة اجلزائيــة مبحافظــة جــدة املســجل‬\n‫بعــدد ‪ 3449400‬وتاريــخ ‪1434/2/27‬هـ ـ املتضمــن دعــوى ‪(...‬مصــري‬\n‫اجلنســية) ضــد ‪ ...‬يف مطالبتــه بإعســاره احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n‫وبــدراس ــة احلكــم وصــورة ضبطــه تقـ ـ ـ ـ ــررت املـ ــوافقـ ـ ـ ــة علــى احلكــم‬\n‫بــرد دعــوى مدعــي االعســار وبــاهلل تعالــى التوفيــق ‪ .‬وصل ــى اهلل عل ــى‬\n                                        ‫نبي ــنا محم ــد وعل ــى آل ــه وصحب ــه وسـلم‪.‬‬\n\n\n\n\n                                                                                          ‫‪176‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":173,"source_page_end":176,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e49c5069aa99ec621bd8c1ebd4b4520be9b3b2339b2de4f8a6121ce0e1429df7","normalized_text_hash":"bc1541623f9b70fdede497483fcf24ce2cf5b2428ec01df1aef793ba57c383bd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p173-3449400"},{"id":"611bf8d2-f55e-5f2a-b5b7-7627f195d43b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -تغرمي املدعي لصالح بيت املال واجلمارك -مطالبة املدعي بإثبات اإلعسار -اشتراط صدور إذن من املقام السامي لسماع دعوى اإلعسار يف دين الدولة -مصادقة املدعى عليها على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدول بإعسار املدعي -احلكم بإثبات اإلعسار .","document_number":"33350955","case_number":"33476478","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/21","year":"1434","subject":"إعسار -تغرمي املدعي لصالح بيت املال واجلمارك -مطالبة املدعي بإثبات اإلعسار -اشتراط صدور إذن من املقام السامي لسماع دعوى اإلعسار يف دين الدولة -مصادقة املدعى عليها على الدعوى سوى اإلعسار -التحري وثبوت اإلعسار -شهادة الشهود العدول بإعسار املدعي -احلكم بإثبات اإلعسار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/7/21 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33350955 :‬‬\n                          ‫َر ْق ُم الدعوى‪33476478 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 3410775‬تاريخه‪1434/11/13 :‬هـ‬\n\n\n       ‫إعســار‪ -‬تغــرمي املدعــي لصالــح بيــت املــال واجلمــارك‪ -‬مطالبــة املدعــي‬\n       ‫بإثبــات اإلعســار‪ -‬اشــتراط صــدور إذن مــن املقــام الســامي لســماع دعــوى‬\n       ‫اإلعســار يف ديــن الدولــة‪ -‬مصادقــة املدعــى عليهــا علــى الدعــوى ســوى‬\n       ‫اإلعســار‪ -‬التحــري وثبــوت اإلعســار‪ -‬شــهادة الشــهود العــدول بإعســار‬\n                                               ‫املدعــي‪ -‬احلكــم بإثبــات اإلعســار ‪.‬‬\n\n\n\n\n                      ‫ان ُذو ُع ْس َر ٍة فَ َن ِظ َر ٌة ِإ َلى َم ْي َس َرةٍ}‪.‬‬\n                                                                            ‫ك َ‬‫‪ .1‬قوله تعالى { َو ِإن َ‬\n                                       ‫‪ .2‬املادة ‪ 8/231‬من نظام املرافعات الشرعية ‪.‬‬\n       ‫‪ .3‬األمــر الســامي الكــرمي رقــم ‪/4785‬م وتاريــخ ‪1431/6/11‬ه ـ املتضمــن‬\n                                                           ‫املوافقــة علــى نظــر دعــوى اإلعســار‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي ضــد منــدوب وزارة املاليــة ومنــدوب مصلحــة اجلمارك بأنه‬\n       ‫صــدر عليــه قــرار وزاري يتضمــن احلكــم بتغرميــه مبلــغ مائــة ألــف ريــال‬\n       ‫لصالــح بيــت مــال املســلمني كمــا صــدر حكــم مــن اجلمــارك مبوجــب‬\n       ‫قــرار اللجنــة اجلمركيــة بإلزامــه بدفــع غرامــة قدرها مليونــان وأربعمائة‬\n       ‫واحــد عشــر ألف ـ ًا وســبعمائة وثالثــة وثالثــون ريــا ًال لصالــح اجلمــارك‬\n       ‫وذلــك التهامــه يف قضيــة أســلحة وقــرر املدعــي أنــه معســر ال ميلــك مــا‬\n\n‫‪177‬‬\n\f‫يســدد بــه الغرامــات‪ ،‬أجــاب مندوبــي اجلمــارك واملاليــة باملصادقــة علــى‬\n‫الدعــوى وعــدم علمهمــا بإعســار املدعــي وأنهمــا ال يعلمــان مــا ًال للمدعــي‬\n‫وأضــاف منــدوب املاليــة أنــه يشــترط أن ال يترتــب علــى إثبــات إعســاره‬\n‫إعفــاؤه مــن الغرامــة وإن تبقــى يف ذمتــه وعــدم احلكــم علــى بيــت مــال‬\n‫املســلمني‪ ،‬بدفــع الغرامــة ألن الغرامــة مســتحقة لبيــت مــال املســلمني‪،‬‬\n‫اطلــع ناظــر القضيــة علــى األمــر الســامي الكــرمي بــاإلذن بســماع دعــوى‬\n‫اإلعســار‪ ،‬مت البحــث والتحــري عــن أمــوال مدعــي اإلعســار مــن اجلهــات‬\n‫ذات العالقــة ولــم يوجــد لــه مــال ميكــن الســداد منــه‪ ،‬أحضــر املدعــي‬\n‫ثالثــة شــهود ومت تعديلهــم شــرع ًا شــهدوا بصحــة الدعــوى‪ ،‬لألســباب‬\n‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة‬\n                                   ‫ك َ‬‫{و ِإن َ‬\n                                            ‫املرصــودة يف نــص احلكــم ولقولــه تعالــى َ‬\n‫ِإ َلــى َم ْي َسـ َـرةٍ}صدر احلكــم بإثبــات إعســار املدعــي‪ ،‬مت الرفــع حملكمــة‬\n                 ‫االســتئناف‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n‫أنــا‪ ........‬القاضــي باحملكمــة العامــة بنجــران بنــاء علــى املعاملــة الــواردة‬\n‫لهــذه احملكمــة بخطــاب ســعادة مديــر إدارة ســجون منطقــة جنــران رقــم‬\n‫‪ 1/31/6829/11‬وتاريــخ ‪1432/07/10‬ه ـ املتعلقــة بدعــوى اإلعســار‬\n‫إثــر الغرامــات املترتبــة عليــه واحملالــة لــي برقــم ‪ 33476478‬يف وتاريــخ‬\n‫‪1433/07/20‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331363390‬وتاريــخ‬\n‫‪1433/07/20‬ه ـ ففــي يــوم األحــد تاريــخ ‪1433/7/20‬ه ـ حضــر ‪........‬‬\n‫ا ســبق‬  ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وادعــى قائـ ً‬\n‫وأن اتهمــت يف قضيــة أســلحة وصــدر علــي حكــم بالقــرار الــوزاري‬\n\n                                                                                            ‫‪178‬‬\n\f      ‫رقــم ‪..........‬يف ‪1430/12/12‬ه ـ وممــا تضمنــه احلكــم تغرميــي مببلــغ‬\n      ‫مائــة ألــف ريــال لصالــح بيــت مــال املســلمني كمــا صــدر علــي حكــم‬\n      ‫مــن اجلمــارك مبوجــب قــرار اللجنــة اجلمركيــة بــ‪ ........‬رقــم ‪ ..........‬لعــام‬\n      ‫‪1425‬ه ـ متضمن ـ ًا إلزامــي بدفــع غرامــة قدرهــا مليونــان وأربعمائــة‬\n      ‫وأحــد عشــر ألف ـ ًا وســبعمائة وثالثــة وثالثــون ريــا ًال لصالــح اجلمــارك‬\n      ‫وأنــا معســر ال أملــك مــا أســدد بــه هــذه الغرامــات لــذا أطلــب إثبــات‬\n      ‫إعســاري يف هــذه الغرامــات هكــذا ادعــى وبعــرض دعــوى املدعــي‬\n      ‫علــى منــدوب اجلمــارك ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ........‬املكلــف بهــذه القضيــة مبوجــب خطــاب ســعادة مديــر عــام‬\n      ‫جمــرك بالــ‪ ........‬رقــم ‪..........‬يف ‪1433/07/19‬ه ـ ومنــدوب وزارة املاليــة‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬املكلــف‬\n      ‫يف هــذه القضيــة مبوجــب خطــاب ســعادة مديــر عــام فــرع وزارة املاليــة‬\n      ‫مبنطقــة جنــران رقــم ‪..........‬يف ‪1433/07/20‬ه ـ أجــاب أو ًال منــدوب‬\n      ‫ا صحيــح مــا ذكــره مدعــي اإلعســار مــن أنــه مت احلكــم‬          ‫اجلمــارك قائـ ً‬\n      ‫عليــه مــن قبــل اجلمــارك بالغرامــة املذكــورة يف دعــواه مبوجــب قــرار‬\n      ‫اللجنــة اجلمركيــة بــ‪ ........‬رقــم ‪..........‬لعــام ‪1425‬ه ـ وال أعلم له أمالك ًا‬\n      ‫ا صحيــح‬    ‫ظاهــرة هكــذا قــرر وأجــاب ثاني ـ ًا منــدوب وزارة املاليــة قائ ـ ً‬\n      ‫مــا ذكــره مدعــي اإلعســار مــن أنــه مت احلكــم عليــه بالقــرار الــوزاري‬\n      ‫املشــار إليــه بالغرامــة املذكــورة التــي يكــون اســتيفائها يكــون لصالــح‬\n      ‫بيــت املــال ( خزينــة الدولــة ) فصحيــح وال أعلــم لــه أمــاك ًا ووزارة املالية‬\n      ‫تشــترط أن ال يترتــب علــى إثبــات إعســاره إعفــاؤه مــن الغرامــة بــل تظــل‬\n      ‫يف ذمتــه حلــن إســقاطها بإجــراء نظامــي وفق ـ ًا لنظــام إيــرادات الدولــة‬\n      ‫الصــادر بقــرار مجلــس الــوزراء رقــم ‪ 359‬وتاريــخ ‪1431/11/17‬ه ـ‬\n\n\n‫‪179‬‬\n\f‫كمــا أطلــب عــدم احلكــم علــى بيــت املــال بدفــع الغرامــة ألن الغرامــة‬\n‫ا لصالــح بيــت املــال هكــذا أجــاب وقــد جــرى االطــاع‬      ‫مســتحقة أص ـ ً‬\n‫علــى اإلذن بســماع دعــوى اإلعســار باألمــر الســامي الكــرمي رقــم‪..........‬‬\n‫وتاريــخ ‪1431/06/11‬ه ـ املتضمــن املوافقــة علــى نظــر دعــوى اإلعســار‬\n‫كمــا ســبقت الكتابــة للجهــات املعنيــة لإلفــادة مبــا لديهــم عــن أمــوال‬\n‫وممتلــكات املذكــور فــورد خطــاب مديــر كهربــاء منطقــة جنــران‬\n‫رقــم ‪..........‬يف ‪1431/01/07‬ه ـ املتضمــن أنــه ال يوجــد لــدى املذكــور‬\n‫اشــتراكات كمــا ورد خطــاب أمــن منطقــة جنــران رقــم ‪ ..........‬يف‬\n‫‪1432/01/06‬ه ـ املتضمــن أنــه لــم يســبق للمذكــور املنــح مبدينــة‬\n‫جنــران أرض ســكنية كمــا اتضــح وجــود رخصــة مكتــب مقــاوالت‬\n‫عامــة باســمه حالتهــا ملغــاة كمــا ورد خطــاب األمــن العــام بالغرفــة‬\n‫التجاريــة الصناعيــة بنجــران رقــم ‪ ..........‬يف ‪1431/01/01‬ه ـ املتضمــن‬\n‫أنــه ليــس للمذكــور أي نشــاط جتــاري أو اشــتراك مســجل لديهــم كمــا‬\n‫ورد خطــاب مديــر عــام اإلدارة العامــة لشــؤون الزراعــة مبنطقــة جنــران‬\n‫رقــم ‪..........‬يف ‪1432/01/16‬ه ـ املتضمــن عــدم اســتفادة املذكور أرض‬\n‫زراعيــة مبنطقــة جنــران كمــا ورد خطــاب مديــر إدارة مــرور منطقــة‬\n‫جنــران رقــم‪ ..........‬يف ‪1432/01/02‬ه ـ وشــفعه صحيفــة الســيارات‬\n‫املتضمنــة أن املذكــور ال ميتلــك أي ســيارة كمــا ورد خطــاب مديــر‬\n‫مؤسســة النقــد العربــي الســعودي بأبهــا رقــم ‪..........‬يف ‪1433/06/14‬ه ـ‬\n‫واملتضمــن أن ملدعــي اإلعســار حســاب جــاري مبصــرف ‪ ........‬ورصيــده‬\n‫صفــر وعضويــة حــواالت مبصــرف ‪ ........‬وعضويــة حــواالت ببنــك البــاد‬\n‫ال من ‪........‬‬‫أ ‪ .‬ه ـ وبطلــب البينــة مــن املدعــي أحضــر للشــهادة وأدائهــا ك ً‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ،........‬و‪ ........‬ســعودي‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬و ‪ ........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ........‬فشــهد كل واحــد منهــم مبفــرده‬\n      ‫ا إننــي أعــرف املدعــي وأشــهد هلل تعالــى أنــه معســر وليــس لديــه‬        ‫قائ ـ ً‬\n      ‫عمــل وال ميلــك مــا يســدد بــه الغرامــات املترتبــة عليــه هكــذا شــهدوا‬\n      ‫وجــرى تعديلهــم مــن قبــل ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدني‬\n      ‫رقــم ‪ ........‬و ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫فبنــاء علــى مــا تقــدم ولصــدور اإلذن بســماع دعــوى إعســار املدعــي‬\n      ‫وملــا جــاء يف شــهادة الشــهود املعدلــن التعديــل الشــرعي وملــا جــاء يف‬\n      ‫إجابــات اجلهــات املعنيــة ولقولــه تعالــى ((وإن كان ذو عســرة فنظــرة إلــى‬\n      ‫ميســرة )) وبنــاء علــى املــادة ‪ 8/231‬مــن نظــام املرافعــات الشــرعية فقــد‬\n      ‫ثبــت لــدي إعســار املدعــي وأمــرت بتنظيــم ذلــك يف صــك شــرعي يرفــق‬\n      ‫باملعاملــة وترفــع حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه و صحبــه وســلم‪ .‬حــرر يف‬\n                                                                        ‫‪1433/7/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1433/11/30‬ه ـ‬\n      ‫وردتنــا املعاملــة مــن محكمــة االســتئناف برقــم ‪ 332117056‬وتاريــخ‬\n      ‫‪1433/11/27‬ه ـ وبرفقهــا قــرار املالحظــة رقــم ‪ 33446890‬يف‬\n      ‫‪1433/11/08‬ه ـ واملتضمــن وحيــث ســبق دراســة الصــك وصورة ضبطه‬\n      ‫ـاء علــى قرارنــا رقم‬‫وأوراق املعاملــة وباالطــاع علــى مــا أجــراه فضيلتــه بنـ ً‬\n      ‫(‪ )33388161‬وتاريــخ ‪1433/08/21‬ه ـ تقــرر إعــادة املعاملــة لفضيلــة‬\n      ‫حاكمهــا ملالحظــة أن فضيلتــه لــم يــدون قــرار الدائــرة املرفــق واملشــار‬\n      ‫إليــه أعــاه بضبــط القضيــة ثــم يلحــق بالصــك حســب املتبــع فعلــى‬\n      ‫فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم واهلل املوفــق وصلــى‬\n\n\n‫‪181‬‬\n\f‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ) قاضــي اســتئناف ‪..........‬‬\n‫ختمــه وتوقيعــه وقاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه ورئيــس الدائــرة‬\n‫‪ ........‬ختمــه وتوقيعــه عليــه أجيــب أصحــاب الفضيلــة بــأن القــرار الســابق‬\n‫رقــم ‪ 33388161‬وتاريــخ ‪1433/08/21‬ه ـ املتضمــن (وبدراســة الصــك‬\n‫وأوراق املعاملــة تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن املعاملــة‬\n‫ليــس بهــا صــورة ضبــط للدعــوى والبــد مــن ذلــك لتدقيــق احلكــم فعلــى‬\n‫فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم واهلل املوفــق) قاضــي‬\n‫اســتئناف ‪ ........‬ختمــه وتوقيعــه وقاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه‬\n‫ورئيــس الدائــرة ‪ ........‬ختمــه وتوقيعــه وعليــه فقــد أكمــل الــازم وأمــرت‬\n‫برفــع كامــل املعاملــة حملكمــة االســتئناف حســب املتبــع وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                         ‫يف ‪1433/11/30‬هــ‪.‬‬\n‫ويف جلســة أخــرى يــوم األربعــاء املوافــق ‪ 1434/03/18‬ه ـ وردتنا املعاملة‬\n‫مــن محكمــة االســتئناف بعســير وبرفقهــا القــرار رقــم ‪3410775‬‬\n‫يف ‪1434/01/13‬ه ـ واملتضمــن (وحيــث ســبق دراســة الصــك وصــورة‬\n‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه‬\n‫بالصــك وصــورة ضبطــه بنــاء علــى قرارنــا رقــم (‪ )33446890‬وتاريــخ‬\n‫‪1433/11/08‬ه ـ تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر)‬\n‫قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه وقاضــي اســتئناف ‪ ........‬ختمــه‬\n‫وتوقيعــه ورئيــس الدائــرة ‪ ........‬ختمــه وتوقيعــه وللبيــان جــرى إثباتــه‬\n‫حتــى ال يخفــى وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n\n\n                                                                                     ‫‪182‬‬\n\f      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامة بنجــران برقم ‪332117056‬‬\n      ‫وتاريــخ ‪1434/2/3‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيل ــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ ........ /‬برقــم ‪ 33350955‬وتاريــخ ‪1433/7/21‬ه ـ‬\n      ‫اخلــاص بدعــوى‪ /‬يف (طلــب إثبــات إعســار) علــى الصفــة املوضحــة يف‬\n      ‫الصــك املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث‬\n      ‫ســبق دراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا‬\n      ‫ـاء علــى قرارنــا رقــم‬\n                           ‫أجــاب بــه فضيلتــه وأحلقــه بالصــك وصــورة ضبطــه بنـ ً‬\n      ‫(‪ )33446890‬وتاريــخ ‪1433/11/8‬هــ‪ .‬تقــررت املوافقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪183‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":177,"source_page_end":183,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a8081d8fd713f93470b2db8719457b4a806de8e4316b57c11ae7fe7d3ea0b94d","normalized_text_hash":"609a86729022268f6327cbe4d3025705c36df5e8042c2f8cb6483b0bccbe7fa1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p177-33350955"},{"id":"722ed736-d6a9-5890-80cd-d574d8a07fce","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -سجن املدين استظهار ا حلاله -إفادة الدوائر واملؤسسات املالية بإعسار املدين -شهادة الشهود العدول -بينة على إعسار املدين -إثبات إعسار املدين وعلى الدائن انظاره إلى ميسرة .","document_number":"33429665","case_number":"1175","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/17","year":"1434","subject":"إعسار -سجن املدين استظهار ا حلاله -إفادة الدوائر واملؤسسات املالية بإعسار املدين -شهادة الشهود العدول -بينة على إعسار املدين -إثبات إعسار املدين وعلى الدائن انظاره إلى ميسرة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/10/17 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33429665 :‬‬\n                         ‫َر ْق ُم الدعوى‪1175 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34281366‬تاريخه‪1434/7/26 :‬هـ‬\n\n\n ‫إعســار ‪ -‬ســجن املديــن اســتظهار ًا حلالــه ‪ -‬إفــادة الدوائــر واملؤسســات‬\n ‫املاليــة بإعســار املديــن ‪ -‬شــهادة الشــهود العــدول ‪ -‬بينــة علــى إعســار‬\n     ‫املديــن ‪ -‬إثبــات إعســار املديــن وعلــى الدائــن انظــاره إلــى ميســرة ‪.‬‬\n\n\n\n\n                        ‫ان ُذو ُع ْس َر ٍة فَ َن ِظ َر ٌة ِإ َلى َم ْي َس َرةٍ}‪.‬‬\n                                                                              ‫ك َ‬‫قوله تعالى { َو ِإن َ‬\n\n\n\n\n ‫ادعــى املدعــي املقيــم (املديــن) يف مواجهــة املدعــى عليــه (الدائــن) بأنــه‬\n ‫حكــم عليــه مبوجــب صــك شــرعي بدفــع مبلــغ مالــي للمدعــى عليــه‬\n ‫(الدائــن)‪ ،‬و أنــه ســجن بســبب ذلــك خمــس ســنوات تقريبـ ًا وقــرر عجــزه‬\n ‫عــن ســداد هــذا املبلــغ وطلــب إثبــات إعســاره يف مواجهــة الدائــن‪ ،‬قــرر‬\n ‫املدعــى عليــه صحــة الديــن مبوجــب الصــك املذكــور كمــا قــرر أنــه ال‬\n ‫يعلــم عــن فقــر املدعــي و أنــه ال يوافــق علــى إثبــات إعســاره‪ ،‬جــرى ســؤال‬\n ‫املدعــى عليــه هــل يعلــم أمــوا ًال للمدعــي (املديــن)‪ ،‬قــرر املدعــى عليــه‬\n ‫أنــه ال يعلــم أمــوا ًال للمدعــي‪ ،‬وردت إفــادة مؤسســه النقــد بعــدم وجــود‬\n ‫أرصــده أو حــواالت للمدعــى‪ ،‬أحضــر املدعــي ثالثــة شــهود فشــهدوا‬\n ‫علــى صحــة دعــواه و أنــه ال توجــد للمدعــى أمــوال ثابتــة أو منقولــة يف‬\n ‫الســعودية أو بلــده‪ ،‬جــرى تعديــل الشــهود‪ ،‬صــدر احلكــم بإثبات إعســار‬\n\n                                                                                                         ‫‪184‬‬\n\f      ‫املدعــي (املديــن) وأن علــى املدعــى عليــه (الدائــن) إنظــاره إلــى ميســرة‪،‬‬\n      ‫اعتــرض املدعــى عليــه علــى احلكم‪،‬صــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬مســاعد رئيــس احملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة ففــي هــذا اليــوم األحــد ‪1433/10/15‬ه ـ الســاعة‬\n      ‫احلاديــة والنصــف افتتحــت بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم (‪ )1175‬وتاريــخ‬\n      ‫‪1431/02/19‬ه ـ واملقيــدة باحملكمــة برقــم (‪ )31/3582‬وتاريــخ‬\n      ‫‪1431/02/19‬ه ـ وفيهــا حضــر ‪ ...‬ســعودي اجلنســية بالســجل املدنــي‬\n      ‫رقــم (‪ )...‬وادعــى يف مواجهــة احلاضــر معــه ‪...‬مصــري اجلنســية مبوجــب‬\n      ‫ا عــن ‪...‬بالوكالــة رقــم (‪)129‬‬      ‫رخصــة اإلقامــة رقــم (‪ )...‬بصفتــه وكيـ ً‬\n      ‫وتاريــخ ‪ 1429/02/23‬الصــادرة مــن ‪...‬كاتــب العــدل املكلــف يف وزارة‬\n      ‫التجــارة والصناعــة بالريــاض املخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n      ‫واملخاصمــة والصلــح واإلقــرار والتنــازل واســتالم املبالــغ واملســتندات‬\n      ‫واألوراق الرســمية ومراجعــة كافــة الدوائــر احلكوميــة ذات العالقــة‬\n      ‫ا يف دعــواه عليــه ســبق وأن حكــم علـ ّـي ملــوكل هــذا احلاضــر معــي‬      ‫قائـ ً‬\n      ‫مببلــغ ســبعمائة وســتة وســبعني ألف ـ ًا وســبعمائة وثمانيــة عشــر ريــال‬\n      ‫(‪ )776718‬مبوجــب الصــك الصــادر منكــم برقــم ‪ 10/14‬وتاريــخ‬\n      ‫‪ 1430/02/14‬وقــد عجــزت عــن ســداد هــذا املبلــغ أو شــيئ ًا منــه بســبب‬\n      ‫فقــري وإعســاري وســجنت مــن تاريــخ ‪1428/06/18‬ه ـ بســبب هــذا‬\n      ‫املبلــغ ومــا زلــت ســجين ًا حتــى اآلن وليــس لــدي مــا أســتطيع الســداد منــه‬\n\n‫‪185‬‬\n\f‫ال ثابــت وال منقــول لــذا أطلــب إثبــات إعســاري يف حــق مــوكل املدعــى‬\n‫عليــه هــذه دعــواي‪ ،‬وبســؤال املدعــى عليــه وكالــة أجــاب بقولــه مــا‬\n‫ذكــره املدعــي مــن احلكــم ملوكلــي عليــه باملبلــغ الــذي ذكــر مبوجــب‬\n‫الصــك الــذي ذكــر وســجنه بســبب ذلــك وعــدم ســداده لشــيء منــه حتــى‬\n‫اآلن فهــذا كلــه صحيــح وأمــا مــا ذكــره مــن فقــره وإعســاره فأنــا ال‬\n‫أعلــم عــن ذلــك شــيئ ًا وال أوافــق املدعــي علــى دعــوى اإلعســار يف حــق‬\n‫موكلــي هــذه إجابتــي فســألت املدعــي عليــه وكالــة هــل يعلــم للمدعــي‬\n‫مــا ًال ثابتـ ًا أو منقــو ًال يف اململكــة أو يف بلــده أو غيــره فقــال ال أعلــم عــن‬\n‫ذلــك شــيئ ًا هــذا وقــد طلبنــا اإلستفســار عــن أمــوال املدعــي فوردنــا إفادة‬\n‫مؤسســة النقــد العربــي رقــم (‪ )208‬وتاريــخ ‪1432/01/19‬ه ـ املتضمنــة‬\n‫أن للمدعــي حســاب يف بنــك ‪ ........‬وحســاب يف بنــك ‪ ........‬ورصيدهــا‬\n‫صفــر كمــا تلقــت املؤسســة إجابــة باقــي البنــوك ومفادهــا عــدم وجــود‬\n‫أيــة أرصــدة أو حســابات أو حــواالت لديهــم أو لــدى فروعهــم العاملــة‬\n‫باململكــة تخــص املذكــور وبطلــب البينــة مــن املدعــي قــال لــدي بينــة‬\n‫فأحضر ‪...‬مصري اجلنسية مبوجب رخصة اإلقامة رقم (‪ )...‬و ‪...‬مصري‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ )...‬و ‪...‬مصــري اجلنســية مبوجــب‬\n‫رخصــة اإلقامــة رقــم (‪ )...‬وباستشــهادهم شــهد كل واحــد منهــم مبفرده‬\n‫ا إننــي أعــرف املدعــي ‪...‬معرفــة تامــة وهــو فقيــر ومعســر مبــا عليــه‬    ‫قائـ ً‬\n‫مــن ديــن وليــس لــه مــال ال ثابــت وال منقــول ال يف اململكــة وال يف بلــده‬\n‫مصــر وال يف أي مــكان وأشــهد أنــه فقيــر ومعســر مبــا عليــه مــن ديــن‬\n‫هكــذا شــهد كل واحــد منهــم وبعــرض الشــهود الثالثــة وشــهادتهم‬\n‫علــى املدعــى عليــه الوكيــل قــال ال أعــرف الشــهود وال أقــول فيهــم شــيئ ًا‬\n‫وبطلــب بينــة التعديــل مــن املدعــي لشــهوده أحضــر ‪...‬مصــري اجلنســية‬\n\n\n                                                                                            ‫‪186‬‬\n\f      ‫مبوجــب رخصــة اإلقامــة رقــم ( ‪ )...‬و ‪...‬مصــري اجلنســية مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم (‪ )...‬و ‪...‬ســوري اجلنســية مبوجــب رخصــة اإلقامــة رقــم(‪)...‬‬\n      ‫ا أشــهد هلل عــز وجــل بــأن‬   ‫وباستشــهادهم شــهد كل واحــد منهمــا قائـ ً‬\n      ‫كل واحــد مــن الشــهود الثالثــة وهــم ‪ ...‬و ‪ ...‬و ‪......‬عــدل ثقــة أمانــة و‬\n      ‫ـاء علــى مــا تقــدم مــن ســماع الدعــوى واإلجابــة‬    ‫ديانــة هكــذا شــهدا فبنـ ً‬\n      ‫ومبــا أن املدعــى عليــه صــادق علــى دعــوى املدعــي مــن أنــه مــدان لــه مببلغ‬\n      ‫ســبعمائة وســتة وســبعني ألفـ ًا وســبعمائة وثمانيــة عشــر ريــال (‪)776718‬‬\n      ‫مبوجــب الصــك املشــار إليــه وأنــه لــم يســدد مــن هــذا املبلــغ شــيء وأنــه‬\n      ‫ســجني بســبب ذلــك وحيــث أفــادت مؤسســة النقــد بعــدم وجــد أمــوال‬\n      ‫للمدعــي أو أرصــدة ماليــة أو حــواالت لديهــم أو لــدى فروعهــم العاملــة‬\n      ‫يف اململكــة تخــص املذكــور ونظــر َا ألن املدعــى عليــه ســجني مــن‬\n      ‫تاريــخ ‪1428/06/18‬ه ـ بســبب املبلــغ املشــار إليــه ونظــر ًا إلــى أن املدعــى‬\n      ‫عليــه أثبــت إعســاره بشــهوده الثالثــة املعدلــن طبــق القاعــدة الشــرعية‬\n      ‫وملجمــوع مــا تقــدم فقــد ثبــت لــدي إعســار املدعــى عليــه ‪...‬مبــا عليــه مــن‬\n      ‫ديــن وعلــى دائنــة إنظــاره إلــى ميســرة لقولــه تعالى (( وإن كان ذو عســرة‬\n      ‫فنظــرة إلــى ميســرة )) هــذا مــا ظهــر لــي وبــه حكمــت وبإعــان احلكــم‬\n      ‫علــى املدعــى عليــه الوكيــل قــرر عــدم قناعتــه باحلكــم وطلــب رفعــه‬\n      ‫إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة وأقفلــت اجللســة يف‬\n      ‫متــام الســاعة الواحــدة ظهــر ًا وعلــى مــا تقــدم حصــل التوقيــع وصلــى اهلل‬\n      ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه حــرر يف ‪1433/10/15‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪-:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n\n\n‫‪187‬‬\n\f‫فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪341362431‬‬\n‫وتاريــخ ‪ 1434/7/8‬ه ـ املرفــق بهــا الصــك الشــرعي رقــم ‪33429665‬‬\n‫وتاريــخ ‪1433/10/17‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ ... /‬القاضــي يف‬\n‫احملكمــة اجلزائيــة باملدينــة املنــورة ‪ ،‬املتضمــن دعــوى‪ ...‬وكالــة ضــد‪/‬‬\n‫‪ ...‬مصــري اجلنســية املتهــم بقضيــة حقوقيــة احملكــوم فيــه مبــا دون‬\n‫باطنــه‪ .‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا‬\n‫املوافقــة علــى احلكــم‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                ‫وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                ‫‪188‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":184,"source_page_end":188,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4ec54c853560d1e17c113ce1595fda699be2591b4e3975d10557246c8f171e6e","normalized_text_hash":"323115c555087d56e88ba2051924ee8374a71df675983dbbccaf65251403bcfc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p184-33429665"},{"id":"4c003b2a-0ffe-58b6-ad87-9a72071d6d2c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -طلب إثبات إعسار يف دفع دية -بحث وحتري عن أموال مدعي اإلعسار -إحضار ثالثة شهود على إثبات دعوى اإلعسار - حكم على املدعى عليه بإنظار مدعي اإلعسار إلى حن ميسرة - احلكم بثبوت إعسار مقيم غير مواطن يف دية قتل اخلطأ .","document_number":"33479731","case_number":"33611080","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/27","year":"1434","subject":"إعسار -طلب إثبات إعسار يف دفع دية -بحث وحتري عن أموال مدعي اإلعسار -إحضار ثالثة شهود على إثبات دعوى اإلعسار - حكم على املدعى عليه بإنظار مدعي اإلعسار إلى حن ميسرة - احلكم بثبوت إعسار مقيم غير مواطن يف دية قتل اخلطأ .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/12/27 :‬هـ‬\n                       ‫ُ‬                  ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪33479731 :‬‬\n                           ‫َر ْق ُم الدعوى‪33611080 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3421069‬تاريخه‪1434/1/24 :‬هـ‬\n\n\n        ‫إعســار ‪ -‬طلــب إثبــات إعســار يف دفــع ديــة ‪ -‬بحــث وحتــري عــن أمــوال‬\n        ‫مدعــي اإلعســار‪ -‬إحضــار ثالثــة شــهود علــى إثبــات دعــوى اإلعســار ‪-‬‬\n        ‫حكــم علــى املدعــى عليــه بإنظــار مدعــي اإلعســار إلــى حــن ميســرة ‪-‬‬\n               ‫احلكــم بثبــوت إعســار مقيــم غيــر مواطــن يف ديــة قتــل اخلطــأ ‪.‬‬\n\n\n\n\n        ‫ان ُذو ُع ْسـ َـر ٍة فَ َن ِظـ َـر ٌة ِإ َلــى َم ْي َسـ َـر ٍة َوأ َْن َت َص َّد ُقــوا‬  ‫ك َ‬   ‫قولــه تعالــى { َو ِإ ْن َ‬\n                                                                                    ‫ـون }‬‫ك ْن ُتـ ْـم َت ْع َل ُمـ َ‬\n                                                                                                                   ‫َخ ْيـ ٌـر َل ُكـ ْـم ِإ ْن ُ‬\n\n\n\n\n        ‫ادعــى املدعــي ضــد املدعــى عليهمــا أصالــة ووكالــة ومضمــون الدعــوى‬\n        ‫أن املدعــي تســبب يف وفــاة مــورث املدعــى عليهــم أصالــة وقــدر نســبة‬\n        ‫اخلطــأ ‪ %75‬وصــدر عليــه حكــم يتضمــن تســليم الورثــة املدعــى عليهــم‬\n        ‫مبلغـ ًا وقــدره مائــة وخمســة وعشــرون ألــف ريــال وأنــه ال يســتطيع ســداد‬\n        ‫املبلــغ احملكــوم بــه وطلــب إثبــات إعســاره واحلكــم علــى الورثــة بإنظــاره‬\n        ‫إلــى حــن ميســرة‪ ،‬أجــاب املدعــى عليهمــا باملصادقــة على الدعوى ســوى‬\n        ‫إعســار املدعــي فــا علــم لهمــا بــه‪ ،‬جــرى التحــري عــن أمــوال مدعــي‬\n        ‫اإلعســار فلــم يظهــر وجــود أمــوال ميكــن الســداد منهــا‪ ،‬مت إحضــار‬\n        ‫ثالثــة شــهود مت تعديلهــم شــهدوا علــى صحــة الدعــوى‪ ،‬لألســباب‬\n\n‫‪189‬‬\n\f‫ان ُذو ُع ْسـ َـر ٍة َف َن ِظـ َـر ٌة‬\n                                    ‫ك َ‬     ‫املرصــودة يف نــص احلكــم ولقولــه تعالــى‪َ {:‬و ِإنْ َ‬\n‫ـون} صــدر احلكــم‬                ‫ك ْن ُتـ ْـم َت ْعل َُمـ َ‬\n                                                           ‫َكـ ْـم ِإنْ ُ‬\n                                                                       ‫ِإ َلــى َم ْي َسـ َـر ٍة َوأَنْ َت َص َّدقُ ــوا َخ ْيـ ٌـر ل ُ‬\n‫بثبــوت اإلعســار وأنظــار املدعــي إلــى حــن ميســرة‪ ،‬قــرر املدعــى عليهمــا‬\n‫عــدم القناعــة‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف بالقصيــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالة لنــا من فضيلة رئيس احملكمة العامة‬\n‫بعنيــزة برقــم ‪ 33611080‬وتاريــخ ‪1433/10/18‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 331620471‬وتاريــخ ‪1433/08/27‬ه ـ حضــر ‪ ........‬باكســتاني‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم وادعــى علــى احلاضريــن معــه‬\n‫األول ‪ ........‬مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ........‬بصفتــه‬\n‫وكيــا عــن ‪ ....‬أصالــة عــن نفســها وبصفتهــا وصيــة علــى أوالدهــا‬\n‫مبوجــب التوكيــل اخلــاص الصــادر مــن جمهوريــة مصــر العربيــة وزارة‬\n‫العــدل مصلحــة الشــهر العقــاري والتوثيــق مكتــب التوثيــق النموذجــي‬\n‫بالــوراق مبحضــر التصديــق رقــم‪ ..........‬لســنة ‪2012‬م واملصدقــة مــن‬\n‫اجلهــات املختصــة يف مصــر واململكــة وبصفتــه وكيــا عــن ‪ ....‬مبوجــب‬\n‫التوكيــل اخلــاص الصــادر مــن جمهوريــة مصــر العربيــة وزارة العــدل‬\n‫مصلحــة الشــهر العقــاري والتوثيــق مكتــب التوثيــق النموذجــي بالــوراق‬\n‫مبحضــر التصديــق رقــم ‪ ..........‬لســنة ‪2012‬م واملصدقــة مــن اجلهــات‬\n‫املختصــة يف مصــر واململكــة وبصفتــه وكيــا عــن ‪ ........‬مبوجــب‬\n‫التوكيــل اخلــاص الصــادر مــن جمهوريــة مصــر العربيــة وزارة العــدل‬\n‫مصلحــة الشــهر العقــاري والتوثيــق مكتــب التوثيــق النموذجــي بالــوراق‬\n                                                                                                                                          ‫‪190‬‬\n\f      ‫مبحضــر التصديــق رقــم ‪ ..........‬لســنة ‪2012‬م واملصدقــة مــن اجلهــات‬\n      ‫املختصــة يف مصــر واململكــة وبصفتــه وكيــا عــن ‪ ........‬مبوجــب‬\n      ‫التوكيــل اخلــاص الصــادر مــن جمهوريــة مصــر العربيــة وزارة العــدل‬\n      ‫مصلحــة الشــهر العقــاري والتوثيــق مكتــب التوثيــق النموذجــي بالــوراق‬\n      ‫مبحضــر التصديــق رقــم ‪..........‬لســنة ‪2012‬م واملصدقــة مــن اجلهــات‬\n      ‫املختصــة يف مصــر واململكــة وبصفتــه وكيــا عــن ‪ ........‬مبوجــب‬\n      ‫التوكيــل اخلــاص الصــادر مــن جمهوريــة مصــر العربيــة وزارة العــدل‬\n      ‫مصلحــة الشــهر العقــاري والتوثيــق مكتــب التوثيــق النموذجــي بالــوراق‬\n      ‫مبحضــر التصديــق رقم‪..........3‬لســنة ‪2012‬م واملصدقــة مــن اجلهــات‬\n      ‫املختصــة يف مصــر واململكــة والثانــي ‪ ........‬مصــري باإلقامــة رقــم ‪........‬‬\n      ‫أصالــة عــن نفســه وبصفتــه وكيــا عــن كل مــن أوالد ‪ ........‬مبوجــب‬\n      ‫التوكيــل اخلــاص الصــادر مــن جمهوريــة مصــر العربيــة وزارة العــدل‬\n      ‫مصلحــة الشــهر العقــاري والتوثيــق مكتــب التوثيــق النموذجــي بالــوراق‬\n      ‫مبحضــر التصديــق رقم‪..........‬لســنة ‪ 2011‬ب لســنة ‪2012‬م واملصدقــة‬\n      ‫مــن اجلهــات املختصــة يف مصــر واململكــة وموكلــو املدعــي واملدعــي‬\n      ‫أصالــة وموكلــوه هــم ورثــة مبوجــب اإلعــام الشــرعي رقــم ‪..........‬لســنة‬\n      ‫‪2011‬م الصــادر مــن جمهوريــة مصــر العربيــة محكمــة الــوراق لشــؤون‬\n      ‫األســرة بتاريــخ ‪2011/12/19‬م مصــدق مــن اجلهــات املختصــة يف مصــر‬\n      ‫واململكــة واملتضمــن وفــاة وانحصــار إرثــه يف زوجتــه وبناتــه وإخوانــه‬\n      ‫األشــقاء حــرر املدعــي دعــواه قائــا بلغــة عربيــة مفهومــة صــدر الصــك‬\n      ‫رقــم ‪ 33363344‬يف ‪1433/7/30‬ه ـ مــن محكمــة عنيــزة املتضمــن‬\n      ‫حكمكــم علــي بــأن أدفــع مبلغــا قــدره مائتــان وخمســة وعشــرون ألــف‬\n      ‫ريــال لورثــة املتوفــى الــذي تــويف يف ‪1432/12/9‬ه ـ يف حــادث مــروري‬\n\n\n‫‪191‬‬\n\f‫أدنــت فيــه بنســبة خمســة وســبعني باملائــة مــن اخلطــأ وقــد اكتســب‬\n‫احلكــم القطعيــة وأنــا ســجني منــذ وقــوع احلــادث يف ‪1432/12/9‬ه ـ‬\n‫وليــس لــدي مــال ثابــت وال منقــول أســدد بــه شــيئا مــن املبلــغ احملكــوم‬\n‫بــه أطلــب إثبــات إعســاري واحلكــم علــى الورثــة املذكوريــن بإنظــاري‬\n‫إلــى ميســرة هــذه دعــواي وبســؤال املدعــى عليهمــا أصالــة ووكالــة عــن‬\n‫دعــوى املدعــي أجــاب كل واحــد منهمــا بقولــه كل ماذكــره املدعــي‬\n‫يف دعــواه صحيــح إال اإلعســار فإننــا ال نعلــم عنــه هكــذا أجــاب كل‬\n‫واحــد منهمــا ويف جلســة أخــرى حضــر مدعــي اإلعســار كمــا حضــر‬\n‫املدعــى عليــه وكالــة ولــم يحضــر املدعــى عليــه اآلخــر وقــد كنــا‬\n‫خاطبنــا مؤسســة النقــد العربــي للتأكــد مــن أرصــدة مدعــي اإلعســار‬\n‫مبوجــب خطابنــا رقــم ‪ 331848230‬يف ‪1433/10/21‬ه ـ ولــم يردنــا‬\n‫إفــادة حتــى اآلن ويف جلســة أخــرى حضــر مدعــي اإلعســار كمــا‬\n‫حضــر املدعــى عليــه وكالــة واملدعــى عليــه أصالــة ووكالــة وقــد وردنــا‬\n‫خطــاب مؤسســة النقــد رقــم ‪..........‬يف ‪1433/12/9‬ه ـ املتضمــن عــدم‬\n‫وجــود أيــة أرصــدة أو حســابات لــدى البنــوك العاملــة باململكــة تخــص‬\n‫مدعــي اإلعســار انتهــى وقــد طلبــت مــن املدعــي البينــة علــى إعســاره‬\n‫فأحضــر كال مــن ‪ ........‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم ‪ ........‬وعمــره ‪ 55‬ســنة و ‪ ........‬باكســتاني اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقــم ‪ ........‬وعمــره ‪24‬ســنة و ‪ ........‬باكســتاني اجلنســية مبوجــب‬\n‫رخصــة اإلقامــة رقــم ‪ ........‬وعمــره ‪52‬ســنة وشــهد كل واحــد منهمــا‬\n‫بلغــة عربيــة مفهومــة قائــا إننــي مــن أهــل املعرفــة اخلاصــة مبدعــي‬\n‫اإلعســار ‪ ..........‬وأشــهد بأنــه معســر ال مــال لديــه ثابــت أو منقــول وال‬\n‫يســتطيع دفــع املبلــغ احملكــوم بــه ولــه يف الســجن أكثــر مــن ســنة وهــو‬\n\n\n                                                                                   ‫‪192‬‬\n\f      ‫عاجــز وفقيــر وال يســتطيع الســداد هكــذا شــهد كل واحــد منهــم بلغــة‬\n      ‫عربيــة مفهومــة واضحــة وبعــرض شــهادتهم علــى املدعــى عليهمــا أصالــة‬\n      ‫ووكالــة قــاال إننــا ال نعــرف الشــهود وال نطعــن فيهــم وال نعلــم عمــا جــاء‬\n      ‫يف شــهادتهم هكــذا قــرر كل واحــد منهمــا وجــرى تعديــل الشــهود‬\n      ‫مــن قبــل ‪ ........‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪........‬‬\n      ‫و‪ ........‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ........‬وشــهد‬\n      ‫املعــدالن بقــول كل واحــد منهمــا بلغــة عربيــة مفهومــة أشــهد بــأن جميــع‬\n      ‫الشــهود املذكوريــن ثقــات وعــدول هكــذا شــهد كل واحــد منهمــا‬\n      ‫فطلبــت مــن مدعــي اإلعســار اليمــن علــى إعســاره اســتظهارا فحلــف‬\n      ‫قائــا واهلل العظيــم إننــي معســر وعاجــز وفقيــر وليــس عنــدي مــال وال‬\n      ‫أســتطيع دفــع املبلــغ املذكــور احملكــوم بــه علــي هكــذا حلــف مدعــي‬\n      ‫اإلعســار وقــد اطلعــت علــى صــك احلكــم فوجدتــه كمــا ذكــر املدعــي‬\n      ‫فبنــاء علــى مــا تقــدم مــن دعــوى مدعــي اإلعســار وملصادقــة املدعــى‬\n      ‫عليهمــا علــى الدعــوى ســوى اإلعســار فقــد قــررا عــدم علمهمــا عنــه وملــا‬\n      ‫جــاء يف إفــادة مؤسســة النقــد مــن عــدم وجــود أرصــدة ملدعــي اإلعســار‬\n      ‫وألن مدعــي اإلعســار مضــى لــه أكثــر مــن ســنة يف الســجن ممــا يــدل‬\n      ‫علــى عجــزه عــن الســداد خاصــة أنــه مــن العمالــة الوافــدة التــي قدمــت‬\n      ‫للبحــث عــن الــرزق والتــي يغلــب عليهــا الفقــر وملــا أحضــره املدعــي مــن‬\n      ‫البينــة املعدلــة التــي شــهدت بإعســاره وألنــه أدى اليمــن اســتظهارا علــى‬\n      ‫إعســاره ولقولــه تعالــى (وإن كان ذو عســرة فنظــرة إلــى ميســرة) وملــا‬\n      ‫تقــدم كلــه فقــد ثبــت لــدي إعســار مدعــي اإلعســار عــن دفــع املبلــغ‬\n      ‫املذكــور احملكــوم عليــه بدفعــه للورثــة املذكوريــن وحكمــت علــى‬\n      ‫الورثــة املذكوريــن بإنظــاره إلــى ميســرة وبعــرض احلكــم علــى املدعــى‬\n\n\n‫‪193‬‬\n\f‫عليهمــا أصالــة ووكالــة قــررا عــدم القناعــة بــه وطلبــا رفــع احلكــم إلــى‬\n‫محكمــة االســتئناف بــدون الئحــة اعتراضيــة وبــاهلل التوفيق وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/12/27‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة القصيــم‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n‫عنيــزة برقــم‪ 331620471‬وتاريــخ ‪1434/ 1 / 7‬هــ؛ واملقيــدة لدينــا‬\n‫برقــم ‪ 3491269‬وتـ ـ ــاريخ ‪1434/1/12‬هــ؛ امل ـ ـ ــرفق بهــا الصــك رق ـ ـ ـ ــم‬\n‫‪ 33479731‬وتاريـ ـ ـ ــخ ‪1433/12/27‬هــ؛ الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫‪ ........‬القاضــي باحملكمــة ‪ ........‬؛ اخلــاص بدعــوى ‪( ........‬باكســتاني‬\n‫اجلنســية) اإلعســار مبواجهــة غرمييــه وهمــا كل مــن‪( ........-1 /‬مصــري‬\n‫اجلنســية)‪( ........-2‬مصــري اجلنســية) وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه بثبــوت إعســار املدعــي علــى النحــو املفصــل فيــه‪ ،‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n‫مــع تنبيــه فضيلتــه بــأن يفهــم املطالبــن بالديــة أن لهــم مطالبــة املتســبب‬\n‫يف وفــاة مورثهــم يف بلــده ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                            ‫وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪194‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":189,"source_page_end":194,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"415b690478f746d64cb0e0fa6461bbab4b9db69734f9b71c570a466a26e6642c","normalized_text_hash":"2f59464bb5a880f5548cc05132af5f8248076a4b8961c6e36ed81f6a7552e725","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p189-33479731"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

